function escapeRegExp(value: string) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function normalizeComparableUrl(value: string) {
  return value.trim().replace(/[)\].,!?;:]+$/g, '').replace(/\/$/, '').toLowerCase()
}

function formatCivilAiShortDateTime(value: string) {
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) return value
  return new Intl.DateTimeFormat('en-CA', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  }).format(parsed)
}

function formatCivilAiCommunityNames(
  communities: Array<{
    communityName: string
  }>,
) {
  const unique = communities
    .map((community) => community.communityName.trim())
    .filter(Boolean)
    .filter((name, index, collection) => collection.indexOf(name) === index)

  if (!unique.length) return 'your Civil communities'
  if (unique.length === 1) return unique[0]
  if (unique.length === 2) return `${unique[0]} and ${unique[1]}`
  return `${unique.slice(0, -1).join(', ')}, and ${unique[unique.length - 1]}`
}

function formatCivilAiSearchScopeLabel(
  communities: Array<{
    communityName: string
  }>,
) {
  return communities.length > 1 ? 'your searched Civil communities' : formatCivilAiCommunityNames(communities)
}

type CivilAiGroundingBundle = {
  retrievalPlan: CivilAiRetrievalPlan
  searchPass: 1 | 2
  targetCommunities: Array<{
    id: string
    communityName: string
    provinceName: string
    communitySlug: string
    provinceCode: string
    href: string
  }>
  events: CivilAiEventDataItem[]
  jobs: CivilAiJobDataItem[]
  market: MarketSearchResultPayload[]
  organizations: CivilAiOrganizationDataItem[]
  posts: CivilAiPostDataItem[]
}

type CivilAiMarketSearchScope = {
  mode: 'global' | 'community' | 'province'
  communities: Array<{ provinceCode: string; communitySlug: string }>
  provinceCodes: string[]
}

function detectCivilAiProfileIntent(question: string) {
  const normalized = question.trim().toLowerCase()
  const asksName = /(what is my name|what'?s my name|do you know my name|who am i|my first name|what is my first name|what'?s my first name|my last name|what is my last name|what'?s my last name|surname|family name|given name)/.test(normalized)
  const asksExperience = /(my experience|my experiences|what experience do i have|what have i done|my background|my work history|my profile)/.test(normalized)
  const asksOrganizations = /(my organizations|what organizations do i belong to|what orgs do i belong to|what groups do i belong to|which organizations am i in|which groups am i in)/.test(normalized)
  const asksBio = /(my bio|my profile bio|what does my bio say)/.test(normalized)
  return {
    asksName,
    asksExperience,
    asksOrganizations,
    asksBio,
    wantsProfile: asksName || asksExperience || asksOrganizations || asksBio,
  }
}

function detectCivilAiAssistantIdentityIntent(question: string) {
  const normalized = question.trim().toLowerCase()
  return /(what is your name|what'?s your name|who are you|who are u|tell me your name|what should i call you|what do i call you)/.test(normalized)
}

export function buildCivilAiGroundedAnswer(question: string, bundle: CivilAiGroundingBundle) {
  const normalized = question.trim().toLowerCase()
  const profileIntent = detectCivilAiProfileIntent(question)
  const asksEvents = bundle.retrievalPlan.wantsEvents
  const asksJobs = bundle.retrievalPlan.wantsJobs
  const asksMarket = bundle.retrievalPlan.wantsMarket
  const asksOrganizations = bundle.retrievalPlan.wantsOrganizations
  const asksPosts = bundle.retrievalPlan.wantsPosts
  const eventIntent = /(what(?:'s| is) happening|going on|anything happening|event|events|meetup|meetups|metup|metups|networking|networking event|networking events|today|tonight|this afternoon|this evening|near me|nearby|attend)/.test(normalized)
  const jobIntent = /(job|jobs|hiring|employment|position|positions|open role|open roles|work near me|jobs near me)/.test(normalized)
  const marketIntent = /(buy|buying|looking for|looking to buy|where can i buy|shopping|shop for|for sale|marketplace|listing|listings|purchase)/.test(normalized)
  const organizationIntent = /(organization|organizations|group|groups|association|associations|who should i talk to|who is working on|which org|which organization|which organizations|which groups)/.test(normalized)
  const postIntent = /(post|posts|discussion|discussions|conversation|conversations|debate|debates|people saying|talking about|discussing|buzz)/.test(normalized)
  const targetLabel = formatCivilAiCommunityNames(bundle.targetCommunities)
  const scopeLabel = formatCivilAiSearchScopeLabel(bundle.targetCommunities)
  const requestedSources = [
    bundle.retrievalPlan.wantsEvents,
    bundle.retrievalPlan.wantsJobs,
    bundle.retrievalPlan.wantsMarket,
    bundle.retrievalPlan.wantsOrganizations,
    bundle.retrievalPlan.wantsPosts,
  ].filter(Boolean).length
  const totalMatches = bundle.events.length + bundle.jobs.length + bundle.market.length + bundle.organizations.length + bundle.posts.length

  const formatCountLabel = (count: number, singular: string, plural: string) => (count === 1 ? `1 ${singular}` : `${count} ${plural}`)

  if (asksMarket && marketIntent) {
    const references = bundle.market.slice(0, 4).map((listing) => toCivilAiMarketReference(listing))
    if (!bundle.market.length) {
      return {
        content: [
          'I could not find any active marketplace listings that match that search right now.',
          'If you want, I can try a broader item keyword or a different product search.',
        ].join('\n\n'),
        references: [] as CivilAiCardReference[],
      }
    }

    return {
      content: `I found ${formatCountLabel(bundle.market.length, 'matching listing', 'matching listings')}. The best match is linked below.`,
      references,
    }
  }

  if (asksEvents && eventIntent) {
    const references = bundle.events.slice(0, 4).map((event) => toCivilAiEventReference(event))
    if (!bundle.events.length) {
      const timing = bundle.retrievalPlan.todayOnly ? 'today' : 'right now'
      return {
        content: [
          `I could not find any events for ${targetLabel} ${timing}.`,
          bundle.organizations.length || bundle.posts.length
            ? 'If helpful, I can still summarize the local organizations or recent posts tied to that area.'
            : 'If you want, I can check local organizations, posts, or another nearby community instead.',
        ].join('\n\n'),
        references: [] as CivilAiCardReference[],
      }
    }

    return {
      content: bundle.events.length === 1
        ? `I found 1 event for ${scopeLabel}${bundle.retrievalPlan.todayOnly ? ' today' : ''}. It is linked below.`
        : `I found ${bundle.events.length} events for ${scopeLabel}${bundle.retrievalPlan.todayOnly ? ' today' : ''}. The best matches are linked below.`,
      references,
    }
  }

  if (asksJobs && jobIntent) {
    const references = bundle.jobs.slice(0, 4).map((job) => toCivilAiJobReference(job)).filter((entry): entry is CivilAiCardReference => Boolean(entry))
    if (!bundle.jobs.length) {
      return {
        content: [
          `I could not find any active jobs for ${targetLabel} right now.`,
        ].join('\n\n'),
        references: [] as CivilAiCardReference[],
      }
    }

    return {
      content: bundle.jobs.length === 1
        ? `I found 1 active job for ${targetLabel}. It is linked below.`
        : `I found ${bundle.jobs.length} active jobs for ${targetLabel}. The best matches are linked below.`,
      references,
    }
  }

  if (asksOrganizations && organizationIntent) {
    const references = bundle.organizations.slice(0, 4).map((organization) => toCivilAiOrganizationReference(organization)).filter((entry): entry is CivilAiCardReference => Boolean(entry))
    if (!bundle.organizations.length) {
      return {
        content: [
          `I could not find any matching organizations for ${targetLabel}.`,
        ].join('\n\n'),
        references: [] as CivilAiCardReference[],
      }
    }

    return {
      content: bundle.organizations.length === 1
        ? `I found 1 matching organization for ${targetLabel}. It is linked below.`
        : `I found ${bundle.organizations.length} matching organizations for ${targetLabel}. The best matches are linked below.`,
      references,
    }
  }

  if (asksPosts && postIntent) {
    const references = bundle.posts.slice(0, 4).map((post) => toCivilAiPostReference(post))
    if (!bundle.posts.length) {
      return {
        content: [
          `I could not find any matching local posts for ${targetLabel}.`,
        ].join('\n\n'),
        references: [] as CivilAiCardReference[],
      }
    }

    return {
      content: bundle.posts.length === 1
        ? `I found 1 matching local post for ${targetLabel}. It is linked below.`
        : `I found ${bundle.posts.length} matching local posts for ${targetLabel}. The best matches are linked below.`,
      references,
    }
  }

  if (!profileIntent.wantsProfile && requestedSources > 0 && totalMatches === 0) {
    return {
      content: [
        `I could not find matching results for ${targetLabel}.`,
      ].join('\n\n'),
      references: [] as CivilAiCardReference[],
    }
  }

  return null
}

export function sanitizeCivilAiResponseContent(content: string, references: CivilAiCardReference[]) {
  let next = content.trim()
  if (!next || !references.length) return next

  const uniqueHrefs = Array.from(
    new Set(
      references
        .map((reference) => reference.href?.trim())
        .filter((href): href is string => Boolean(href)),
    ),
  )

  for (const href of uniqueHrefs) {
    const normalizedHref = normalizeComparableUrl(href)
    if (!normalizedHref) continue

    const escapedHref = escapeRegExp(href)
    next = next.replace(new RegExp(`\\[([^\\]]+)\\]\\(${escapedHref}\\)`, 'gi'), '$1')
    next = next.replace(new RegExp(`\\(?${escapedHref}\\)?`, 'gi'), 'the Civil card below')
  }

  next = next
    .replace(/^view\s+(event|job|community|organization|post):\s*$/gim, '')
    .replace(/here:\s*the Civil card below/gi, 'in the Civil card below')
    .replace(/details\s+about\s+it\s+the Civil card below/gi, 'details in the Civil card below')
    .replace(/\(\s*the Civil card below\s*\)/gi, 'the Civil card below')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim()

  return next
}

function serializeCivilAiViewerContext(viewerContext: CivilAiViewerContext | null) {
  if (!viewerContext) return null
  return {
    user: viewerContext.user,
    homeCommunity: viewerContext.homeCommunity,
    nearbyCommunities: viewerContext.nearbyCommunities,
    followedCommunities: viewerContext.followedCommunities,
    organizations: viewerContext.organizations,
    feedContext: {
      viewerId: viewerContext.feedContext.viewerId,
      homeCommunityKey: viewerContext.feedContext.homeCommunityKey,
      friendIds: Array.from(viewerContext.feedContext.friendIds),
      connectionIds: Array.from(viewerContext.feedContext.connectionIds),
      followedBusinessIds: Array.from(viewerContext.feedContext.followedBusinessIds),
      memberBusinessIds: Array.from(viewerContext.feedContext.memberBusinessIds),
      nearbyCommunityKeys: Array.from(viewerContext.feedContext.nearbyCommunityKeys),
      regionalCommunityKeys: Array.from(viewerContext.feedContext.regionalCommunityKeys),
      followedCommunityKeys: Array.from(viewerContext.feedContext.followedCommunityKeys),
    },
  }
}

export function buildCivilAiDirectAnswer(question: string, viewerContext: CivilAiViewerContext | null) {
  if (detectCivilAiAssistantIdentityIntent(question)) {
    return {
      content: 'I am Civil AI, your civic assistant inside Civil Citizens.',
      references: [] as CivilAiCardReference[],
    }
  }

  if (!viewerContext) return null
  const normalized = question.trim().toLowerCase()
  const { asksName, asksExperience, asksOrganizations, asksBio } = detectCivilAiProfileIntent(question)
  const asksFirstName = /(my first name|what is my first name|what'?s my first name|given name)/.test(normalized)
  const asksLastName = /(my last name|what is my last name|what'?s my last name|surname|family name)/.test(normalized)

  if (!asksName && !asksExperience && !asksOrganizations && !asksBio) return null

  const lines: string[] = []
  const references: CivilAiCardReference[] = []

  if (asksName) {
    const displayName = viewerContext.user.name || [viewerContext.user.firstName, viewerContext.user.lastName].filter(Boolean).join(' ').trim() || `@${viewerContext.user.handle}`
    if (asksFirstName && viewerContext.user.firstName) {
      lines.push(`Your first name on Civil is ${viewerContext.user.firstName}.`)
    } else if (asksLastName && viewerContext.user.lastName) {
      lines.push(`Your last name on Civil is ${viewerContext.user.lastName}.`)
    } else {
      lines.push(`Your name on Civil is ${displayName}.`)
    }
  }

  if (asksBio) {
    lines.push(viewerContext.user.bio ? `Your Civil bio says: ${viewerContext.user.bio}` : 'I do not see a bio in your Civil profile yet.')
  }

  if (asksExperience) {
    if (viewerContext.user.experiences.length) {
      const summary = viewerContext.user.experiences
        .slice(0, 3)
        .map((experience) => `${experience.title} at ${experience.organization}${experience.current ? ' (current)' : ''}`)
        .join('; ')
      lines.push(`Your experience on file includes ${summary}.`)
      for (const experience of viewerContext.user.experiences.slice(0, 3)) {
        if (!experience.organizationProfile) continue
        const reference = toCivilAiOrganizationReference({
          ...experience.organizationProfile,
          role: undefined,
          description: null,
          communityName: null,
        })
        if (reference) references.push(reference)
      }
    } else {
      lines.push('I do not see any experience entries in your Civil profile yet.')
    }
  }

  if (asksOrganizations) {
    if (viewerContext.organizations.length) {
      const summary = viewerContext.organizations
        .slice(0, 4)
        .map((org) => `${org.name} (${org.role})`)
        .join('; ')
      lines.push(`Your Civil organization context includes ${summary}.`)
      for (const org of viewerContext.organizations.slice(0, 4)) {
        const reference = toCivilAiOrganizationReference({ ...org, description: null, communityName: null })
        if (reference) references.push(reference)
      }
    } else {
      lines.push('I do not see any organizations linked to your Civil account yet.')
    }
  }

  return {
    content: lines.join('\n\n').trim(),
    references: references.slice(0, 4),
    decision: {
      type: 'direct-profile-answer',
      asksName,
      asksExperience,
      asksOrganizations,
      asksBio,
    },
  }
}

async function persistCivilAiDebugTurn(args: {
  conversationId: string
  userId: string | null
  latestUserMessage: string
  requestMessages: Array<{ role: 'system' | 'user' | 'assistant'; content: string }>
  viewerContext: CivilAiViewerContext | null
  retrievalDebug: unknown
  references: CivilAiCardReference[]
  serverName: string | null
  model: string | null
  upstreamInput: string | null
  assistantContent: string | null
  rawResponse: unknown
  status: string
  errorMessage: string | null
  durationMs: number | null
}) {
  await ensureCivilAiDebugTables()

  const userHandle = args.viewerContext?.user.handle ?? null
  const userName = args.viewerContext?.user.name ?? null
  const now = new Date()

  await prisma.$executeRaw`
    INSERT INTO civil_ai_conversation (
      id, user_id, user_handle, user_name, started_at, last_activity_at, turn_count, first_user_message, last_user_message, status, last_model, last_server, last_error
    )
    VALUES (
      ${args.conversationId}, ${args.userId}, ${userHandle}, ${userName}, ${now}, ${now}, 1, ${args.latestUserMessage || null}, ${args.latestUserMessage || null}, ${args.status}, ${args.model}, ${args.serverName}, ${args.errorMessage}
    )
    ON CONFLICT (id) DO UPDATE SET
      user_id = COALESCE(civil_ai_conversation.user_id, EXCLUDED.user_id),
      user_handle = COALESCE(EXCLUDED.user_handle, civil_ai_conversation.user_handle),
      user_name = COALESCE(EXCLUDED.user_name, civil_ai_conversation.user_name),
      last_activity_at = EXCLUDED.last_activity_at,
      turn_count = civil_ai_conversation.turn_count + 1,
      first_user_message = COALESCE(civil_ai_conversation.first_user_message, EXCLUDED.first_user_message),
      last_user_message = EXCLUDED.last_user_message,
      status = EXCLUDED.status,
      last_model = EXCLUDED.last_model,
      last_server = EXCLUDED.last_server,
      last_error = EXCLUDED.last_error
  `

  await prisma.$executeRaw`
    INSERT INTO civil_ai_turn (
      id, conversation_id, user_id, created_at, latest_user_message, status, duration_ms, server_name, model, error_message, assistant_content,
      request_messages_text, viewer_context_text, retrieval_debug_text, references_text, upstream_input_text, raw_response_text
    )
    VALUES (
      ${randomUUID()}, ${args.conversationId}, ${args.userId}, ${now}, ${args.latestUserMessage || null}, ${args.status}, ${args.durationMs}, ${args.serverName}, ${args.model}, ${args.errorMessage}, ${args.assistantContent},
      ${safeJsonStringify(args.requestMessages)}, ${safeJsonStringify(serializeCivilAiViewerContext(args.viewerContext))}, ${safeJsonStringify(args.retrievalDebug)}, ${safeJsonStringify(args.references)}, ${args.upstreamInput}, ${typeof args.rawResponse === 'string' ? args.rawResponse : safeJsonStringify(args.rawResponse)}
    )
  `
}

async function callCivilAiServer(args: {
  server: CivilAiServerConfig
  path: string
  method?: 'GET' | 'POST'
  body?: Record<string, unknown>
  timeoutMs?: number | null
  signal?: AbortSignal
}) {
  const timeoutMs = args.timeoutMs === undefined ? CIVIL_AI_SERVER_TIMEOUT_MS : args.timeoutMs
  const controller = new AbortController()
  const onAbort = () => controller.abort(args.signal?.reason)
  const timeout =
    timeoutMs && timeoutMs > 0
      ? setTimeout(() => controller.abort(), timeoutMs)
      : null
  if (args.signal) {
    if (args.signal.aborted) {
      controller.abort(args.signal.reason)
    } else {
      args.signal.addEventListener('abort', onAbort, { once: true })
    }
  }

  let response: Response
  try {
    response = await fetch(`${args.server.baseUrl}${args.path}`, {
      method: args.method ?? (args.body ? 'POST' : 'GET'),
      headers: args.body ? { 'content-type': 'application/json' } : undefined,
      body: args.body ? JSON.stringify(args.body) : undefined,
      signal: controller.signal,
    })
  } catch (error) {
    if (timeout) clearTimeout(timeout)
    if (args.signal) {
      args.signal.removeEventListener('abort', onAbort)
    }
    const message =
      error instanceof Error && error.name === 'AbortError'
        ? args.signal?.aborted
          ? 'ai_upstream_cancelled'
          : 'ai_upstream_timeout'
        : error instanceof Error
          ? error.message
          : 'ai_upstream_request_failed'
    return {
      ok: false,
      status: 504,
      text: message,
      json: null,
    }
  }
  if (timeout) clearTimeout(timeout)
  if (args.signal) {
    args.signal.removeEventListener('abort', onAbort)
  }

  const rawText = await response.text()
  let json: unknown = null
  if (rawText) {
    try {
      json = JSON.parse(rawText)
    } catch {
      json = null
    }
  }

  return {
    ok: response.ok,
    status: response.status,
    text: rawText,
    json,
  }
}

async function resolveCivilAiServer(serverId?: string | null) {
  const config = await loadCivilAiServersConfig()
  const server = config.servers.find((entry) => entry.id === serverId) || config.servers.find((entry) => entry.id === config.defaultServerId) || config.servers[0] || null
  return { ...config, server }
}

async function resolveCivilAiModel(server: CivilAiServerConfig, preferredModel?: string | null) {
  if (preferredModel?.trim()) return preferredModel.trim()

  const cached = civilAiResolvedModelCache.get(server.id)
  if (cached && cached.expiresAt > Date.now()) {
    return cached.model
  }

  const upstream = await callCivilAiServer({ server, path: '/api/v1/models', method: 'GET' })
  if (!upstream.ok) {
    civilAiResolvedModelCache.set(server.id, { model: null, expiresAt: Date.now() + 10_000 })
    return null
  }

  const payload = upstream.json as Record<string, unknown> | null
  const rawItems = Array.isArray(payload?.data)
    ? payload?.data
    : Array.isArray(payload?.models)
      ? payload?.models
      : Array.isArray(upstream.json)
        ? upstream.json
        : []

  for (const entry of rawItems) {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) continue
    const model = entry as Record<string, unknown>
    if (model.type && model.type !== 'llm') continue

    const loadedInstances = Array.isArray(model.loaded_instances) ? model.loaded_instances : []
    const loadedInstance = loadedInstances.find((item) => item && typeof item === 'object' && typeof (item as Record<string, unknown>).id === 'string') as Record<string, unknown> | undefined
    if (typeof loadedInstance?.id === 'string' && loadedInstance.id.trim()) {
      const model = loadedInstance.id.trim()
      civilAiResolvedModelCache.set(server.id, { model, expiresAt: Date.now() + CIVIL_AI_MODEL_CACHE_TTL_MS })
      return model
    }

    if (typeof model.selected_variant === 'string' && model.selected_variant.trim()) {
      const selectedModel = model.selected_variant.trim()
      civilAiResolvedModelCache.set(server.id, { model: selectedModel, expiresAt: Date.now() + CIVIL_AI_MODEL_CACHE_TTL_MS })
      return selectedModel
    }
    if (typeof model.key === 'string' && model.key.trim()) {
      const selectedModel = model.key.trim()
      civilAiResolvedModelCache.set(server.id, { model: selectedModel, expiresAt: Date.now() + CIVIL_AI_MODEL_CACHE_TTL_MS })
      return selectedModel
    }
    if (typeof model.id === 'string' && model.id.trim()) {
      const selectedModel = model.id.trim()
      civilAiResolvedModelCache.set(server.id, { model: selectedModel, expiresAt: Date.now() + CIVIL_AI_MODEL_CACHE_TTL_MS })
      return selectedModel
    }
  }

  civilAiResolvedModelCache.set(server.id, { model: null, expiresAt: Date.now() + 10_000 })
  return null
}

function readCivilAiBody(req: FastifyRequest) {
  const body = req.body
  if (!body || typeof body !== 'object' || Array.isArray(body)) return null
  return body as Record<string, unknown>
}

function buildCivilCommunityHref(provinceCode: string, communitySlug: string) {
  return `${getCivilPublicBaseUrl()}/${provinceCode.toLowerCase()}/${communitySlug.toLowerCase()}`
}

function buildCivilOrganizationHref(args: { provinceCode: string | null; communitySlug: string | null; slug: string }) {
  if (!args.provinceCode || !args.communitySlug) return null
  return `${getCivilPublicBaseUrl()}/com/${args.provinceCode.toLowerCase()}/${args.communitySlug.toLowerCase()}/orgs/${args.slug}`
}

function buildCivilEventHref(args: { organizationId: string; eventId: string; provinceCode: string | null; communitySlug: string | null; slug: string }) {
  if (args.provinceCode && args.communitySlug) {
    return `${getCivilPublicBaseUrl()}/com/${args.provinceCode.toLowerCase()}/${args.communitySlug.toLowerCase()}/orgs/${args.slug}/events/${args.eventId}`
  }
  return `${getCivilPublicBaseUrl()}/events/${args.organizationId}/${args.eventId}`
}

function buildCivilJobHref(args: { jobId: string; provinceCode: string | null; communitySlug: string | null; slug: string }) {
  if (!args.provinceCode || !args.communitySlug) return null
  return `${getCivilPublicBaseUrl()}/com/${args.provinceCode.toLowerCase()}/${args.communitySlug.toLowerCase()}/orgs/${args.slug}/jobs/${args.jobId}`
}

function buildCivilPostHref(path: string | null) {
  if (!path) return null
  if (/^https?:\/\//i.test(path)) return path
  return `${getCivilPublicBaseUrl()}${path.startsWith('/') ? path : `/${path}`}`
}

function parseCivilAiCommunityId(value: string) {
  const trimmed = value.trim()
  const [provinceCode, communitySlug] = trimmed.split(':')
  if (!provinceCode || !communitySlug) return null
  const normalizedProvince = normalizeProvinceCode(provinceCode)
  if (!normalizedProvince) return null
  const normalizedCommunitySlug = communitySlug.trim().toLowerCase()
  const community = findCommunity(normalizedProvince, normalizedCommunitySlug)
  if (!community) return null
  return {
    id: `${community.province}:${community.slug}`,
    provinceCode: community.province,
    communitySlug: community.slug,
    communityName: community.name ?? community.slug,
    provinceName: getProvinceDisplayName(community.province as any) ?? community.province.toUpperCase(),
    href: buildCivilCommunityHref(community.province, community.slug),
  }
}

const CivilAiCommunityIdParams = z.object({
  communityId: z.string().trim().min(3).max(80),
})

const CivilAiScopedDataQuery = z.object({
  limit: z.coerce.number().int().min(1).max(12).default(6),
  when: z.enum(['today', 'upcoming']).default('upcoming'),
})

const CivilAiSearchableDataQuery = z.object({
  limit: z.coerce.number().int().min(1).max(12).default(6),
  q: z.string().trim().min(1).max(120).optional(),
})

async function authorizeCivilAiDataRequest(req: FastifyRequest) {
  const authContext = await loadViewerAuthContext(req)
  if (authContext?.actor === 'family_member') {
    return { error: 'family_mode_not_available' as const }
  }

  const userId = await resolveUserId(req)
  if (userId) return { userId }

  const providedKey = typeof req.headers['x-civil-ai-key'] === 'string' ? req.headers['x-civil-ai-key'].trim() : ''
  if (CIVIL_AI_DATA_KEY && providedKey === CIVIL_AI_DATA_KEY) return { userId: null }
  return null
}

