async function loadCivilAiViewerContext(userId: string): Promise<CivilAiViewerContext | null> {
  const [user, follows, businessFollows, memberships, ownedOrganizations, feedContext] = await Promise.all([
    prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        handle: true,
        name: true,
        bio: true,
        avatarUrl: true,
        coverUrl: true,
        premiumStatus: true,
        communityMeta: true,
      },
    }),
    prisma.communityFollow.findMany({
      where: { userId },
      orderBy: [{ home: 'desc' }, { createdAt: 'asc' }],
      take: 30,
      select: { provinceCode: true, communitySlug: true, home: true },
    }),
    prisma.businessFollow.findMany({
      where: { userId },
      orderBy: [{ createdAt: 'desc' }],
      take: 30,
      select: {
        business: {
          select: {
            id: true,
            name: true,
            slug: true,
            provinceCode: true,
            communitySlug: true,
            logoUrl: true,
            coverUrl: true,
          },
        },
      },
    }),
    prisma.businessMembership.findMany({
      where: { userId },
      orderBy: [{ createdAt: 'desc' }],
      take: 30,
      select: {
        role: true,
        business: {
          select: {
            id: true,
            name: true,
            slug: true,
            provinceCode: true,
            communitySlug: true,
            logoUrl: true,
            coverUrl: true,
          },
        },
      },
    }),
    prisma.business.findMany({
      where: { ownerId: userId },
      orderBy: [{ createdAt: 'desc' }],
      take: 30,
      select: {
        id: true,
        name: true,
        slug: true,
        provinceCode: true,
        communitySlug: true,
        logoUrl: true,
        coverUrl: true,
      },
    }),
    loadViewerFeedContext(userId),
  ])

  if (!user) return null

  let experienceItems: CivilAiViewerContext['user']['experiences'] = []
  try {
    const experiences = await prisma.experience.findMany({
      where: { userId },
      orderBy: [{ position: 'asc' }, { startDate: 'desc' }],
    })

    const normalizedExperienceOrganizationNames = Array.from(
      new Set(
        experiences
          .map((exp: ExperienceModel) => exp.organization.trim().toLowerCase())
          .filter((name: string) => name.length > 0),
      ),
    )

    const organizationByName = new Map<
      string,
      {
        id: string
        name: string
        slug: string
        href: string | null
        logoUrl: string | null
        coverUrl: string | null
      }
    >()

    if (normalizedExperienceOrganizationNames.length > 0) {
      const linkedOrganizations = await prisma.business.findMany({
        where: {
          status: 'ACTIVE',
          moderationStatus: ModerationStatus.VISIBLE,
          OR: normalizedExperienceOrganizationNames.map((name) => ({
            name: {
              equals: name,
              mode: 'insensitive',
            },
          })),
        },
        orderBy: [{ isVerified: 'desc' }, { name: 'asc' }],
        select: {
          id: true,
          name: true,
          slug: true,
          provinceCode: true,
          communitySlug: true,
          logoUrl: true,
          coverUrl: true,
        },
      })

      for (const org of linkedOrganizations) {
        const key = org.name.trim().toLowerCase()
        if (!key || organizationByName.has(key)) continue
        organizationByName.set(key, {
          id: org.id,
          name: org.name,
          slug: org.slug,
          href: buildCivilOrganizationHref({ provinceCode: org.provinceCode, communitySlug: org.communitySlug, slug: org.slug }),
          logoUrl: normalizeMediaUrl(org.logoUrl ?? null),
          coverUrl: normalizeMediaUrl(org.coverUrl ?? null),
        })
      }
    }

    experienceItems = experiences.map((exp: ExperienceModel) => ({
      id: exp.id,
      title: exp.title,
      organization: exp.organization,
      location: exp.location ?? null,
      startDate: exp.startDate.toISOString(),
      endDate: exp.endDate ? exp.endDate.toISOString() : null,
      current: exp.current,
      description: exp.description ?? null,
      organizationProfile: organizationByName.get(exp.organization.trim().toLowerCase()) ?? null,
    }))
  } catch (err) {
    if (!isExperienceTableMissing(err)) throw err
  }

  const nameParts = (user.name ?? '').trim().split(/\s+/).filter(Boolean)
  const firstName = nameParts[0] ?? null
  const lastName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : null

  const typedFollows = follows as Array<{ provinceCode: string; communitySlug: string; home: boolean }>
  const homeFollow = typedFollows.find((entry: { provinceCode: string; communitySlug: string; home: boolean }) => entry.home) ?? typedFollows[0] ?? null
  const homeCommunity = homeFollow
    ? parseCivilAiCommunityId(`${homeFollow.provinceCode}:${homeFollow.communitySlug}`)
    : null

  const nearbyCommunities = (parseCommunityMeta(user.communityMeta ?? null)?.nearbyCommunities ?? [])
    .map((entry: { provinceCode: string; communitySlug: string }) => parseCivilAiCommunityId(`${entry.provinceCode}:${entry.communitySlug}`))
    .filter((entry: NonNullable<typeof homeCommunity> | null): entry is NonNullable<typeof homeCommunity> => Boolean(entry))
    .slice(0, 8)

  const followedCommunities = typedFollows
    .map((follow: { provinceCode: string; communitySlug: string; home: boolean }) => {
      const parsed = parseCivilAiCommunityId(`${follow.provinceCode}:${follow.communitySlug}`)
      if (!parsed) return null
      return {
        ...parsed,
        isHome: Boolean(follow.home),
      }
    })
    .filter(
      (
        entry: {
          id: string
          provinceCode: string
          provinceName: string
          communitySlug: string
          communityName: string
          href: string
          isHome: boolean
        } | null,
      ): entry is {
        id: string
        provinceCode: string
        provinceName: string
        communitySlug: string
        communityName: string
        href: string
        isHome: boolean
      } => Boolean(entry),
    )

  const organizationsMap = new Map<string, CivilAiViewerContext['organizations'][number]>()
  for (const org of ownedOrganizations) {
    organizationsMap.set(org.id, {
      id: org.id,
      name: org.name,
      slug: org.slug,
      provinceCode: org.provinceCode,
      communitySlug: org.communitySlug,
      role: 'owner',
      href: buildCivilOrganizationHref({ provinceCode: org.provinceCode, communitySlug: org.communitySlug, slug: org.slug }),
      logoUrl: normalizeMediaUrl(org.logoUrl ?? null),
      coverUrl: normalizeMediaUrl(org.coverUrl ?? null),
    })
  }
  for (const row of memberships) {
    if (!row.business || organizationsMap.has(row.business.id)) continue
    organizationsMap.set(row.business.id, {
      id: row.business.id,
      name: row.business.name,
      slug: row.business.slug,
      provinceCode: row.business.provinceCode,
      communitySlug: row.business.communitySlug,
      role: 'member',
      href: buildCivilOrganizationHref({ provinceCode: row.business.provinceCode, communitySlug: row.business.communitySlug, slug: row.business.slug }),
      logoUrl: normalizeMediaUrl(row.business.logoUrl ?? null),
      coverUrl: normalizeMediaUrl(row.business.coverUrl ?? null),
    })
  }
  for (const row of businessFollows) {
    if (!row.business || organizationsMap.has(row.business.id)) continue
    organizationsMap.set(row.business.id, {
      id: row.business.id,
      name: row.business.name,
      slug: row.business.slug,
      provinceCode: row.business.provinceCode,
      communitySlug: row.business.communitySlug,
      role: 'followed',
      href: buildCivilOrganizationHref({ provinceCode: row.business.provinceCode, communitySlug: row.business.communitySlug, slug: row.business.slug }),
      logoUrl: normalizeMediaUrl(row.business.logoUrl ?? null),
      coverUrl: normalizeMediaUrl(row.business.coverUrl ?? null),
    })
  }

  return {
    user: {
      id: user.id,
      handle: user.handle,
      firstName,
      lastName,
      name: user.name,
      bio: user.bio ? sanitizePlainText(user.bio) : null,
      avatarUrl: normalizeMediaUrl(user.avatarUrl ?? null),
      coverUrl: normalizeMediaUrl(user.coverUrl ?? null),
      isVerified: isSelfVerifiedCanadianCitizen(parseCommunityMeta(user.communityMeta ?? null)),
      isPremium: Boolean(user.premiumStatus),
      experiences: experienceItems,
    },
    homeCommunity,
    nearbyCommunities,
    followedCommunities,
    organizations: Array.from(organizationsMap.values()).slice(0, 12),
    feedContext,
  }
}

function buildCivilAiApiCatalog(viewerContext: CivilAiViewerContext | null) {
  const apiBaseUrl = getCivilApiBaseUrl()
  const suggestedCommunityId = viewerContext?.homeCommunity?.id ?? viewerContext?.followedCommunities[0]?.id ?? 'ON:newmarket'
  return [
    {
      name: 'Current User Context',
      endpoint: `${apiBaseUrl}/ai/context`,
      purpose: 'Current signed-in user profile, home community, nearby communities, followed communities, and organizations.',
    },
    {
      name: 'Community Summary',
      endpoint: `${apiBaseUrl}/ai/communities/${encodeURIComponent(suggestedCommunityId)}`,
      purpose: 'Structured community identity and direct Civil URL for a community.',
    },
    {
      name: 'Community Events',
      endpoint: `${apiBaseUrl}/ai/events/${encodeURIComponent(suggestedCommunityId)}?when=today`,
      purpose: 'Upcoming or today-only events for a specific community. Filters out stale events.',
    },
    {
      name: 'Community Jobs',
      endpoint: `${apiBaseUrl}/ai/jobs/${encodeURIComponent(suggestedCommunityId)}`,
      purpose: 'Active jobs in a community from local organizations or local job locations.',
    },
    {
      name: 'Marketplace Listings',
      endpoint: `${apiBaseUrl}/ai/market?q=skateboard`,
      purpose: 'Active marketplace listings that match a shopping or buying query.',
    },
    {
      name: 'Community Organizations',
      endpoint: `${apiBaseUrl}/ai/organizations/${encodeURIComponent(suggestedCommunityId)}`,
      purpose: 'Active organizations in a specific community, optionally filtered by a topic query.',
    },
    {
      name: 'Community Posts',
      endpoint: `${apiBaseUrl}/ai/posts/${encodeURIComponent(suggestedCommunityId)}`,
      purpose: 'Recent public posts in a specific community, optionally filtered by a topic query.',
    },
  ]
}

function buildCivilAiCompactList(items: string[], emptyLabel: string, limit = 4) {
  const normalized = items.map((item) => item.trim()).filter(Boolean)
  if (!normalized.length) return emptyLabel
  const visible = normalized.slice(0, limit)
  const remainder = normalized.length - visible.length
  return remainder > 0 ? `${visible.join('; ')}; +${remainder} more` : visible.join('; ')
}

function buildCivilAiContextSummary(viewerContext: CivilAiViewerContext | null) {
  if (!viewerContext) {
    return ['- Authenticated user context: unavailable']
  }

  const displayName = viewerContext.user.name || [viewerContext.user.firstName, viewerContext.user.lastName].filter(Boolean).join(' ').trim() || `@${viewerContext.user.handle}`
  const nearby = buildCivilAiCompactList(viewerContext.nearbyCommunities.map((community) => community.communityName), 'none', 4)
  const followed = buildCivilAiCompactList(viewerContext.followedCommunities.map((community) => community.communityName), 'none', 5)
  const organizations = buildCivilAiCompactList(viewerContext.organizations.map((organization) => `${organization.name} (${organization.role})`), 'none', 5)
  const experiences = buildCivilAiCompactList(viewerContext.user.experiences.map((experience) => `${experience.title} at ${experience.organization}${experience.current ? ' (current)' : ''}`), 'none', 4)

  return [
    `- User: ${displayName} (@${viewerContext.user.handle})`,
    viewerContext.user.bio ? `- Bio: ${truncateCivilAiText(viewerContext.user.bio, 180)}` : '- Bio: none',
    `- Home community: ${viewerContext.homeCommunity ? viewerContext.homeCommunity.communityName : 'none'}`,
    `- Nearby communities: ${nearby}`,
    `- Followed communities: ${followed}`,
    `- Organizations: ${organizations}`,
    `- Experience: ${experiences}`,
  ]
}

function buildCivilAiCatalogSummary(viewerContext: CivilAiViewerContext | null) {
  return buildCivilAiApiCatalog(viewerContext).map((entry) => `- ${entry.name}: ${entry.purpose}`)
}

function buildCivilAiContextPrompt(viewerContext: CivilAiViewerContext | null) {
  return [
    'Current Civil User Context:',
    ...buildCivilAiContextSummary(viewerContext),
    '',
    'Available Civil AI Data Endpoints:',
    ...buildCivilAiCatalogSummary(viewerContext),
    '',
    'Rules for signed-in user context:',
    '- If a current signed-in user context block is present, you do know that user\'s provided profile data for this conversation.',
    '- You may use the provided first name, last name, display name, experience history, home community, and organizations to answer personally relevant questions.',
    '- The signed-in user context describes the user, not the assistant.',
    '- If the user asks who you are or asks for your name, answer as Civil AI and do not answer with the signed-in user\'s profile.',
    '- Do not claim you lack access to the user\'s name or organizations if those fields are present in the context block.',
    '- Only say information is unavailable when the specific field is actually missing from the provided context.',
    '',
    'Rules for local data answers:',
    '- Prefer the current user context over generic assumptions.',
    '- You do not have any external events, jobs, organization, or post database beyond the provided Civil data for this question.',
    '- Never invent events, jobs, organizations, posts, communities, counts, dates, addresses, or links that are not present in the provided Civil data.',
    '- Never imply there are more matching Civil items than were actually returned.',
    '- Prefer home, nearby, or followed communities before anything farther away.',
    '- For events, ignore stale past items unless the user explicitly asks about history.',
    '- If the request asks about today, only use today-filtered events.',
    '- For posts and organizations, prefer matches from the target local communities before broader discovery.',
    '- If live data is missing, say that plainly instead of inventing specifics.',
  ].join('\n')
}

