app.post('/family/members/:id/lock-device-session', async (req: FastifyRequest, reply: FastifyReply) => {
  const params = z.object({ id: z.string().trim().min(1) }).safeParse(req.params)
  if (!params.success) return reply.code(400).send({ error: params.error.flatten() })

  const parent = await loadAuthenticatedUser(req)
  if (!parent) return reply.code(401).send({ error: 'unauthorized' })

  let member: Awaited<ReturnType<typeof loadFamilyMemberAuthViewerById>>
  try {
    member = await loadFamilyMemberAuthViewerById(params.data.id, parent.id)
  } catch (error) {
    if (isFamilyMemberTableMissing(error)) {
      return reply.code(503).send({ error: 'family_mode_not_available' })
    }
    throw error
  }

  if (!member) return reply.code(404).send({ error: 'family_member_not_found' })

  const token = await (app as any).jwt.sign({
    sub: member.id,
    actor: 'family_member',
    parentId: parent.id,
  } satisfies AuthJwtPayload)

  const homeCommunity = await buildHomeCommunitySummaryForUserId(parent.id)
  return reply.send({
    ok: true,
    token,
    viewer: buildFamilyMemberAuthMeResponse(member, homeCommunity),
  })
})

app.get('/family/feed/posts', async (req: FastifyRequest, reply: FastifyReply) => {
  const authContext = await loadViewerAuthContext(req)
  if (!authContext) {
    return reply.code(401).send({ error: 'unauthorized' })
  }

  const query = z.object({ memberId: z.string().trim().min(1).optional() }).safeParse(req.query ?? {})
  if (!query.success) return reply.code(400).send({ error: query.error.flatten() })

  const targetMember = await resolveReadableFamilyFeedTargetMember(authContext, query.data.memberId)
  if (!targetMember) {
    return reply.code(authContext.actor === 'user' ? 400 : 404).send({
      error: authContext.actor === 'user' ? 'family_member_required' : 'family_member_not_found',
    })
  }

  const rows: Array<{
    id: string
    body: string
    images: Prisma.JsonValue
    createdAt: Date
    updatedAt: Date
  }> = await prisma.post.findMany({
    where: {
      authorId: targetMember.parentId,
      type: FAMILY_FEED_POST_TYPE,
      title: buildFamilyFeedPostTitle(targetMember.id),
    },
    orderBy: [{ createdAt: 'desc' }],
    take: 40,
    select: {
      id: true,
      body: true,
      images: true,
      createdAt: true,
      updatedAt: true,
    },
  })

  const normalizedMember = normalizeFamilyMemberSummary(targetMember)
  return reply.send({
    items: rows.map((row) =>
      formatFamilyFeedPost(
        {
          id: row.id,
          familyMemberId: targetMember.id,
          body: row.body,
          images: row.images,
          createdAt: row.createdAt,
          updatedAt: row.updatedAt,
        },
        normalizedMember,
      ),
    ),
  })
})

app.post('/family/feed/posts', async (req: FastifyRequest, reply: FastifyReply) => {
  const authContext = await loadViewerAuthContext(req)
  if (!authContext) {
    return reply.code(401).send({ error: 'unauthorized' })
  }

  const parse = z.object({
    memberId: z.string().trim().min(1).optional(),
    body: z.string().trim().max(2000).optional().default(''),
    images: z.array(z.string().trim().url()).max(6).optional().default([]),
  }).safeParse(req.body ?? {})
  if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

  const targetMember = await resolveFamilyFeedTargetMember(authContext, parse.data.memberId)
  if (!targetMember) {
    return reply.code(authContext.actor === 'user' ? 400 : 404).send({
      error: authContext.actor === 'user' ? 'family_member_required' : 'family_member_not_found',
    })
  }

  const body = sanitizePlainText(parse.data.body)
  const images = parse.data.images.filter(Boolean)
  if (!body && images.length === 0) {
    return reply.code(400).send({ error: 'family_feed_post_empty' })
  }

  const created = await prisma.post.create({
    data: {
      authorId: targetMember.parentId,
      type: FAMILY_FEED_POST_TYPE,
      title: buildFamilyFeedPostTitle(targetMember.id),
      body,
      images: images.length ? (images as any) : undefined,
      audience: 'family',
      visibility: 'public',
      jurisdiction: 'self',
    },
    select: {
      id: true,
      body: true,
      images: true,
      createdAt: true,
      updatedAt: true,
    },
  })

  const normalizedMember = normalizeFamilyMemberSummary(targetMember)
  return reply.code(201).send({
    post: formatFamilyFeedPost(
      {
        id: created.id,
        familyMemberId: targetMember.id,
        body: created.body,
        images: created.images,
        createdAt: created.createdAt,
        updatedAt: created.updatedAt,
      },
      normalizedMember,
    ),
  })
})

app.post('/family/friends/requests', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const authContext = await loadViewerAuthContext(req)
    if (!authContext) return reply.code(401).send({ error: 'unauthorized' })
    if (authContext.actor !== 'family_member') return reply.code(403).send({ error: 'family_member_required' })

    const parse = FamilyFriendRequestInput.safeParse(req.body ?? {})
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const vagueResponse = {
      ok: true,
      message: "An invite has been sent to this user's parent or guardian if it exists.",
    }

    const inviteCode = parse.data.inviteCode?.trim() ?? ''
    const username = parse.data.username?.trim() ?? ''

    let targetMember: Awaited<ReturnType<typeof loadFamilyMemberAuthViewerById>> = null
    if (inviteCode) {
      targetMember = await findFamilyMemberByInviteCode(inviteCode)
    }
    if (!targetMember && username) {
      targetMember = await findFamilyMemberByUsername(username)
    }

    if (!targetMember) return reply.send(vagueResponse)
    if (targetMember.id === authContext.member.id || targetMember.parentId === authContext.member.parentId) {
      return reply.send(vagueResponse)
    }

    const requesterFriendships = getStoredFamilyFriendships(authContext.member.parent.communityMeta)
    const targetFriendships = getStoredFamilyFriendships(targetMember.parent.communityMeta)
    if (
      hasAcceptedFamilyFriendship(requesterFriendships, authContext.member.id, targetMember.id) ||
      hasAcceptedFamilyFriendship(targetFriendships, targetMember.id, authContext.member.id)
    ) {
      return reply.send(vagueResponse)
    }

    const requesterRequests = getStoredFamilyFriendRequests(authContext.member.parent.communityMeta)
    const targetRequests = getStoredFamilyFriendRequests(targetMember.parent.communityMeta)
    if (
      findPendingFamilyFriendRequest(requesterRequests, authContext.member.id, targetMember.id) ||
      findPendingFamilyFriendRequest(targetRequests, authContext.member.id, targetMember.id)
    ) {
      return reply.send(vagueResponse)
    }

    const requesterSummary = normalizeFamilyMemberSummary(authContext.member)
    const targetSummary = normalizeFamilyMemberSummary(targetMember)
    const requestId = randomUUID()
    const createdAt = new Date().toISOString()
    const requestRecord: FamilyFriendRequestRecord = {
      id: requestId,
      requesterParentId: authContext.member.parentId,
      requesterMemberId: authContext.member.id,
      requesterDisplayName: requesterSummary.displayName,
      requesterUsername: requesterSummary.username,
      requesterAvatarUrl: requesterSummary.avatarUrl ?? null,
      requesterCoverUrl: requesterSummary.coverUrl ?? null,
      requesterParentHandle: authContext.member.parent.handle,
      requesterParentName: authContext.member.parent.name,
      requesterParentAvatarUrl: authContext.member.parent.avatarUrl ?? null,
      requesterParentCoverUrl: authContext.member.parent.coverUrl ?? null,
      targetParentId: targetMember.parentId,
      targetMemberId: targetMember.id,
      targetDisplayName: targetSummary.displayName,
      targetUsername: targetSummary.username,
      targetAvatarUrl: targetSummary.avatarUrl ?? null,
      targetCoverUrl: targetSummary.coverUrl ?? null,
      status: 'pending',
      createdAt,
      respondedAt: null,
    }

    const requesterBaseMeta = readBaseCommunityMeta(authContext.member.parent.communityMeta ?? null)
    writeStoredFamilyFriendRequests(requesterBaseMeta, upsertFamilyFriendRequest(requesterRequests, requestRecord))

    const targetBaseMeta = readBaseCommunityMeta(targetMember.parent.communityMeta ?? null)
    writeStoredFamilyFriendRequests(targetBaseMeta, upsertFamilyFriendRequest(targetRequests, requestRecord))

    await prisma.$transaction([
      prisma.user.update({
        where: { id: authContext.member.parentId },
        data: { communityMeta: requesterBaseMeta as Prisma.InputJsonValue },
      }),
      prisma.user.update({
        where: { id: targetMember.parentId },
        data: { communityMeta: targetBaseMeta as Prisma.InputJsonValue },
      }),
    ])

    await createNotificationRecord({
      userId: targetMember.parentId,
      actorId: authContext.member.parentId,
      type: FAMILY_NOTIFICATION_TYPES.FRIEND_REQUEST,
      payload: {
        requestId,
        status: 'pending',
        url: '/notifications',
        sourceUrl: '/notifications',
        requesterChild: {
          id: requesterSummary.id,
          displayName: requesterSummary.displayName,
          username: requesterSummary.username,
          avatarUrl: requesterSummary.avatarUrl,
          coverUrl: requesterSummary.coverUrl,
        },
        targetChild: {
          id: targetSummary.id,
          displayName: targetSummary.displayName,
          username: targetSummary.username,
          avatarUrl: targetSummary.avatarUrl,
          coverUrl: targetSummary.coverUrl,
        },
      },
    })

    return reply.send(vagueResponse)
  }),
)

app.get('/family/username/check', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const authContext = await loadViewerAuthContext(req)
    if (!authContext) return reply.code(401).send({ error: 'unauthorized' })
    if (authContext.actor !== 'family_member') return reply.code(403).send({ error: 'family_member_required' })

    const query = z.object({ username: z.string().trim().min(1).max(40) }).safeParse(req.query ?? {})
    if (!query.success) return reply.code(400).send({ error: query.error.flatten() })

    const username = normalizeFamilyMemberUsernameCandidate(query.data.username)
    if (!isValidFamilyMemberUsername(username)) {
      return reply.code(400).send({
        error: 'family_member_username_invalid',
        requirements: {
          min: FAMILY_MEMBER_USERNAME_MIN_LENGTH,
          max: FAMILY_MEMBER_USERNAME_MAX_LENGTH,
          pattern: 'letters_and_numbers_only',
        },
      })
    }

    const currentUsername = normalizeFamilyMemberUsernameLookup(authContext.member.username ?? '')
    if (currentUsername && currentUsername === normalizeFamilyMemberUsernameLookup(username)) {
      return reply.send({ ok: true, username, available: true })
    }

    const available = !(await isFamilyMemberUsernameTaken(username, { excludeMemberId: authContext.member.id }))
    return reply.send({ ok: true, username, available })
  }),
)

app.put('/family/username', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const authContext = await loadViewerAuthContext(req)
    if (!authContext) return reply.code(401).send({ error: 'unauthorized' })
    if (authContext.actor !== 'family_member') return reply.code(403).send({ error: 'family_member_required' })
    if (!authContext.member.allowChildOwnUsernameEdits) {
      return reply.code(403).send({ error: 'family_member_username_edit_not_allowed' })
    }

    const parse = z.object({ username: z.string().trim().min(1).max(40) }).safeParse(req.body ?? {})
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const username = normalizeFamilyMemberUsernameCandidate(parse.data.username)
    if (!isValidFamilyMemberUsername(username)) {
      return reply.code(400).send({
        error: 'family_member_username_invalid',
        requirements: {
          min: FAMILY_MEMBER_USERNAME_MIN_LENGTH,
          max: FAMILY_MEMBER_USERNAME_MAX_LENGTH,
          pattern: 'letters_and_numbers_only',
        },
      })
    }

    const currentUsername = normalizeFamilyMemberUsernameLookup(authContext.member.username ?? '')
    if (currentUsername !== normalizeFamilyMemberUsernameLookup(username)) {
      const taken = await isFamilyMemberUsernameTaken(username, { excludeMemberId: authContext.member.id })
      if (taken) return reply.code(409).send({ error: 'family_member_username_taken' })
    }

    let updatedMember: Awaited<ReturnType<typeof loadFamilyMemberSummaryForParent>> = null

    try {
      const memberWithUsername = await prisma.familyMember.update({
        where: { id: authContext.member.id },
        data: { username },
        select: {
          id: true,
          parentId: true,
          firstName: true,
          lastName: true,
          dateOfBirth: true,
          relationship: true,
          friendCode: true,
          username: true,
          avatarUrl: true,
          coverUrl: true,
          allowChildOwnMediaEdits: true,
          allowChildOwnUsernameEdits: true,
          notifyParentOnMediaChanges: true,
          suspendedAt: true,
          suspendedById: true,
          suspensionNote: true,
          createdAt: true,
          updatedAt: true,
        },
      })
      updatedMember = memberWithUsername
    } catch (error) {
      if (!isFamilyMemberTableMissing(error)) throw error

      const parent = await prisma.user.findUnique({
        where: { id: authContext.member.parentId },
        select: { communityMeta: true },
      })
      const baseMeta = readBaseCommunityMeta(parent?.communityMeta ?? null)
      writeLegacyFamilyMemberUsername(baseMeta, authContext.member.id, username)
      await prisma.user.update({
        where: { id: authContext.member.parentId },
        data: {
          communityMeta: baseMeta as Prisma.InputJsonValue,
        },
      })

      updatedMember = {
        ...authContext.member,
        username,
      }
    }

    if (!updatedMember) return reply.code(500).send({ error: 'family_member_username_update_failed' })

    void createNotificationRecord({
      userId: updatedMember.parentId,
      actorId: updatedMember.id,
      type: FAMILY_NOTIFICATION_TYPES.USERNAME_CHANGED,
      payload: {
        memberId: updatedMember.id,
        childDisplayName: `${updatedMember.firstName} ${updatedMember.lastName}`.trim(),
        username,
        url: '/settings/family/settings',
        sourceUrl: '/settings/family/settings',
      },
    }).catch((error) => {
      req.log.error({ err: error, memberId: updatedMember?.id }, 'family_username_change_notification_failed')
    })

    const refreshedMember = await loadFamilyMemberAuthViewerById(updatedMember.id, updatedMember.parentId)
    if (!refreshedMember) return reply.code(401).send({ error: 'unauthorized' })
    const homeCommunity = await buildHomeCommunitySummaryForUserId(updatedMember.parentId)

    return reply.send({
      ok: true,
      username,
      member: normalizeFamilyMemberSummary(updatedMember),
      viewer: buildFamilyMemberAuthMeResponse(refreshedMember, homeCommunity),
    })
  }),
)

app.delete('/family/members/:id', async (req: FastifyRequest, reply: FastifyReply) => {
  const userId = (req as any).user?.id
  if (!userId) return reply.code(401).send({ error: 'unauthorized' })

  const params = z.object({ id: z.string().cuid() }).safeParse(req.params ?? {})
  if (!params.success) return reply.code(400).send({ error: params.error.flatten() })

  const bodyParse = z
    .object({
      confirmationName: z.string().trim().min(1).max(120),
    })
    .safeParse(req.body ?? {})
  if (!bodyParse.success) return reply.code(400).send({ error: bodyParse.error.flatten() })

  let existing
  try {
    existing = await prisma.familyMember.findFirst({
      where: { id: params.data.id, parentId: userId },
      select: { id: true, firstName: true, lastName: true },
    })
  } catch (error) {
    if (isFamilyMemberTableMissing(error)) {
      return reply.code(503).send({ error: 'family_mode_not_available' })
    }
    throw error
  }

  if (!existing) return reply.code(404).send({ error: 'family_member_not_found' })

  const expectedName = `${existing.firstName} ${existing.lastName}`.trim().toLowerCase()
  const providedName = bodyParse.data.confirmationName.trim().toLowerCase()
  if (expectedName !== providedName) {
    return reply.code(400).send({ error: 'family_member_confirmation_mismatch' })
  }

  try {
    await prisma.familyMember.delete({ where: { id: params.data.id } })
  } catch (error) {
    if (isFamilyMemberTableMissing(error)) {
      return reply.code(503).send({ error: 'family_mode_not_available' })
    }
    throw error
  }
  return reply.send({ ok: true })
})

app.post('/family/members/:id/media', async (req: FastifyRequest, reply: FastifyReply) => {
  const authContext = await loadViewerAuthContext(req)
  if (!authContext) return reply.code(401).send({ error: 'unauthorized' })

  const params = z.object({ id: z.string().cuid() }).safeParse(req.params ?? {})
  if (!params.success) return reply.code(400).send({ error: params.error.flatten() })

  const body = z.object({
    category: z.enum(['avatar', 'cover']),
    displayAssetId: MediaAssetIdSchema,
  }).safeParse(req.body ?? {})
  if (!body.success) return reply.code(400).send({ error: body.error.flatten() })

  try {
    const member =
      authContext.actor === 'family_member'
        ? await loadFamilyMemberAuthViewerById(params.data.id, authContext.member.parentId)
        : await loadFamilyMemberSummaryForParent(params.data.id, authContext.userId)

    if (!member) return reply.code(404).send({ error: 'family_member_not_found' })
    if (authContext.actor === 'family_member') {
      if (member.id !== authContext.member.id) {
        return reply.code(403).send({ error: 'family_member_media_edit_not_allowed' })
      }
      if (!member.allowChildOwnMediaEdits) {
        return reply.code(403).send({ error: 'family_member_media_edit_not_allowed' })
      }
    }

    const asset = await prisma.mediaAsset.findFirst({
      where: {
        id: body.data.displayAssetId,
        ownerId: member.parentId,
        category: body.data.category,
      },
    })
    if (!asset) return reply.code(404).send({ error: 'display_asset_not_found' })
    if (asset.status === 'failed') return reply.code(400).send({ error: 'display_asset_failed' })
    if (asset.status !== 'ready') return reply.code(409).send({ error: 'display_asset_not_ready' })
    if (authContext.actor === 'family_member' && !familyMemberOwnsAssetForSession(asset, authContext.member.id)) {
      return reply.code(403).send({ error: 'asset_not_owned_by_family_member' })
    }

    const displayUrl = extractVariantUrl(
      asset.variants,
      body.data.category === 'avatar' ? ['avatar@2x', 'avatar@1x', 'avatar-thumb'] : ['cover-xl', 'cover-lg', 'cover-md'],
    )
    if (!displayUrl) return reply.code(400).send({ error: 'display_variant_missing' })

    let updatedMember
    try {
      updatedMember = await prisma.familyMember.update({
        where: { id: member.id },
        data: body.data.category === 'avatar' ? { avatarUrl: displayUrl } : { coverUrl: displayUrl },
        select: {
          id: true,
          parentId: true,
          firstName: true,
          lastName: true,
          dateOfBirth: true,
          relationship: true,
          friendCode: true,
          avatarUrl: true,
          coverUrl: true,
          allowChildOwnMediaEdits: true,
          notifyParentOnMediaChanges: true,
          suspendedAt: true,
          suspendedById: true,
          suspensionNote: true,
          createdAt: true,
          updatedAt: true,
        },
      })
    } catch (error) {
      if (!isFamilyMemberTableMissing(error)) throw error

      const legacyUpdatedMember = await prisma.familyMember.update({
        where: { id: member.id },
        data: body.data.category === 'avatar' ? { avatarUrl: displayUrl } : { coverUrl: displayUrl },
        select: {
          id: true,
          parentId: true,
          firstName: true,
          lastName: true,
          dateOfBirth: true,
          relationship: true,
          friendCode: true,
          avatarUrl: true,
          coverUrl: true,
          suspendedAt: true,
          suspendedById: true,
          suspensionNote: true,
          createdAt: true,
          updatedAt: true,
        },
      })

      updatedMember = {
        ...legacyUpdatedMember,
        allowChildOwnMediaEdits: member.allowChildOwnMediaEdits,
        notifyParentOnMediaChanges: member.notifyParentOnMediaChanges,
      }
    }

    if (authContext.actor === 'family_member' && updatedMember.notifyParentOnMediaChanges) {
      void createNotificationRecord({
        userId: updatedMember.parentId,
        actorId: updatedMember.id,
        type: FAMILY_NOTIFICATION_TYPES.MEDIA_CHANGED,
        payload: {
          memberId: updatedMember.id,
          childDisplayName: `${updatedMember.firstName} ${updatedMember.lastName}`.trim(),
          category: body.data.category,
          url: `/settings/family/edit?id=${encodeURIComponent(updatedMember.id)}`,
          sourceUrl: `/settings/family/edit?id=${encodeURIComponent(updatedMember.id)}`,
        },
      }).catch((error) => {
        req.log.error({ err: error, memberId: updatedMember?.id }, 'family_media_change_notification_failed')
      })
    }

    if (authContext.actor === 'family_member') {
      const refreshedMember = await loadFamilyMemberAuthViewerById(updatedMember.id, updatedMember.parentId)
      if (!refreshedMember) return reply.code(401).send({ error: 'unauthorized' })
      const homeCommunity = await buildHomeCommunitySummaryForUserId(updatedMember.parentId)
      return reply.send({
        ok: true,
        member: normalizeFamilyMemberSummary(updatedMember),
        viewer: buildFamilyMemberAuthMeResponse(refreshedMember, homeCommunity),
      })
    }

    return reply.send({
      ok: true,
      member: normalizeFamilyMemberSummary(updatedMember),
    })
  } catch (error) {
    if (isFamilyMemberTableMissing(error)) {
      return reply.code(503).send({ error: 'family_mode_not_available' })
    }
    throw error
  }
})

// Profile photo update + post
app.post('/profile/photo', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const authContext = await loadViewerAuthContext(req)
    if (!authContext) return reply.code(401).send({ error: 'unauthorized' })
    const ownerUserId = authContext.actor === 'family_member' ? authContext.member.parentId : authContext.userId

    const parsed = UpdateProfilePhotoInput.safeParse(req.body)
    if (!parsed.success) return reply.code(400).send({ error: parsed.error.flatten() })

    const { category, displayAssetId, fullAssetId, caption } = parsed.data

    const displayAsset = await prisma.mediaAsset.findFirst({ where: { id: displayAssetId, ownerId: ownerUserId, category } })
    if (!displayAsset) return reply.code(404).send({ error: 'display_asset_not_found' })
    if (displayAsset.status === 'failed') return reply.code(400).send({ error: 'display_asset_failed' })
    if (displayAsset.status !== 'ready') return reply.code(409).send({ error: 'display_asset_not_ready' })
    if (authContext.actor === 'family_member' && !familyMemberOwnsAssetForSession(displayAsset, authContext.member.id)) {
      return reply.code(403).send({ error: 'asset_not_owned_by_family_member' })
    }

    const fullAsset = await prisma.mediaAsset.findFirst({ where: { id: fullAssetId, ownerId: ownerUserId } })
    if (!fullAsset) return reply.code(404).send({ error: 'full_asset_not_found' })
    if (fullAsset.status === 'failed') return reply.code(400).send({ error: 'full_asset_failed' })
    if (fullAsset.status !== 'ready') return reply.code(409).send({ error: 'full_asset_not_ready' })
    if (authContext.actor === 'family_member' && !familyMemberOwnsAssetForSession(fullAsset, authContext.member.id)) {
      return reply.code(403).send({ error: 'asset_not_owned_by_family_member' })
    }

    const displayVariantPreference = category === 'avatar' ? ['avatar@2x', 'avatar@1x', 'avatar-thumb'] : ['cover-xl', 'cover-lg', 'cover-md']
    const displayUrl = extractVariantUrl(displayAsset.variants, displayVariantPreference)
    if (!displayUrl) return reply.code(400).send({ error: 'display_variant_missing' })

    const postVariantPreference = (() => {
      if (fullAsset.category === 'post_image') {
        return ['post-xl', 'post-lg', 'post-md']
      }
      if (fullAsset.category === 'cover') {
        return ['cover-xl', 'cover-lg', 'cover-md']
      }
      return ['avatar@2x', 'avatar@1x', 'avatar-thumb']
    })()
    const postMediaUrl = extractVariantUrl(fullAsset.variants, postVariantPreference)
    if (!postMediaUrl) return reply.code(400).send({ error: 'full_variant_missing' })

    const baseBody = category === 'avatar' ? 'Updated profile photo.' : 'Updated cover photo.'
    const body = caption?.trim() ? caption.trim() : baseBody

    if (authContext.actor === 'family_member') {
      if (!authContext.member.allowChildOwnMediaEdits) {
        return reply.code(403).send({ error: 'family_member_media_edit_not_allowed' })
      }

      let updatedMember: Awaited<ReturnType<typeof loadFamilyMemberSummaryForParent>> = null
      let createdFamilyPost: {
        id: string
        body: string
        images: Prisma.JsonValue
        createdAt: Date
        updatedAt: Date
      } | null = null

      try {
        createdFamilyPost = await prisma.post.create({
          data: {
            authorId: authContext.member.parentId,
            body,
            images: [postMediaUrl] as any,
            type: FAMILY_FEED_POST_TYPE,
            title: buildFamilyFeedPostTitle(authContext.member.id),
            audience: 'family',
            visibility: 'public',
            jurisdiction: 'self',
          },
          select: {
            id: true,
            body: true,
            images: true,
            createdAt: true,
            updatedAt: true,
          },
        })
      } catch (error) {
        if (!isSchemaOutOfDateError(error)) throw error
      }

      try {
        const memberWithMediaColumns = await prisma.familyMember.update({
          where: { id: authContext.member.id },
          data: category === 'avatar' ? { avatarUrl: displayUrl } : { coverUrl: displayUrl },
          select: {
            id: true,
            parentId: true,
            firstName: true,
            lastName: true,
            dateOfBirth: true,
            relationship: true,
            friendCode: true,
            avatarUrl: true,
            coverUrl: true,
            suspendedAt: true,
            suspendedById: true,
            suspensionNote: true,
            createdAt: true,
            updatedAt: true,
          },
        })
        updatedMember = {
          ...memberWithMediaColumns,
          allowChildOwnMediaEdits: authContext.member.allowChildOwnMediaEdits,
          notifyParentOnMediaChanges: authContext.member.notifyParentOnMediaChanges,
        }
      } catch (error) {
        if (!isFamilyMemberTableMissing(error)) throw error

        const parent = await prisma.user.findUnique({
          where: { id: authContext.member.parentId },
          select: { communityMeta: true },
        })
        const baseMeta = readBaseCommunityMeta(parent?.communityMeta ?? null)
        writeLegacyFamilyMemberProfileMedia(baseMeta, authContext.member.id, {
          ...(category === 'avatar' ? { avatarUrl: displayUrl } : {}),
          ...(category === 'cover' ? { coverUrl: displayUrl } : {}),
        })
        await prisma.user.update({
          where: { id: authContext.member.parentId },
          data: {
            communityMeta: baseMeta as Prisma.InputJsonValue,
          },
        })

        updatedMember = {
          ...authContext.member,
          ...(category === 'avatar' ? { avatarUrl: displayUrl } : {}),
          ...(category === 'cover' ? { coverUrl: displayUrl } : {}),
        }
      }

      if (!updatedMember) return reply.code(500).send({ error: 'family_member_update_failed' })

      if (updatedMember.notifyParentOnMediaChanges) {
        void createNotificationRecord({
          userId: updatedMember.parentId,
          actorId: updatedMember.id,
          type: FAMILY_NOTIFICATION_TYPES.MEDIA_CHANGED,
          payload: {
            memberId: updatedMember.id,
            childDisplayName: `${updatedMember.firstName} ${updatedMember.lastName}`.trim(),
            category,
            url: `/settings/family/settings`,
            sourceUrl: `/settings/family/settings`,
          },
        }).catch((error) => {
          req.log.error({ err: error, memberId: updatedMember?.id }, 'family_profile_photo_notification_failed')
        })
      }

      const homeCommunity = await buildHomeCommunitySummaryForUserId(updatedMember.parentId)
      const refreshedMember = {
        ...updatedMember,
        parent: authContext.member.parent,
      }

      return reply.send({
        ok: true,
        post: createdFamilyPost
          ? formatFamilyFeedPost(
              {
                id: createdFamilyPost.id,
                familyMemberId: updatedMember.id,
                body: createdFamilyPost.body,
                images: createdFamilyPost.images,
                createdAt: createdFamilyPost.createdAt,
                updatedAt: createdFamilyPost.updatedAt,
              },
              normalizeFamilyMemberSummary(updatedMember),
            )
          : null,
        viewer: buildFamilyMemberAuthMeResponse(refreshedMember, homeCommunity),
      })
    }

    const author = await prisma.user.findUnique({ where: { id: ownerUserId }, select: { id: true, handle: true, name: true, avatarUrl: true, premiumStatus: true } })
    if (!author) return reply.code(401).send({ error: 'unauthorized' })

    const result = await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
      const post = await tx.post.create({
        data: {
          authorId: ownerUserId,
          body,
          mediaUrl: postMediaUrl,
          type: 'post',
          jurisdiction: 'self',
        },
        include: {
          author: {
            select: {
              id: true,
              handle: true,
              name: true,
              avatarUrl: true,
              premiumStatus: true,
            },
          },
        },
      })

      const userUpdate: Prisma.UserUncheckedUpdateInput =
        category === 'avatar'
          ? { avatarMediaId: displayAsset.id, avatarUrl: displayUrl, avatarPostId: post.id }
          : { coverMediaId: displayAsset.id, coverUrl: displayUrl, coverPostId: post.id }

      const updatedUser = await tx.user.update({
        where: { id: ownerUserId },
        data: userUpdate,
        select: {
          id: true,
          email: true,
          handle: true,
          name: true,
          bio: true,
          avatarUrl: true,
          coverUrl: true,
          avatarMediaId: true,
          coverMediaId: true,
          avatarPostId: true,
          coverPostId: true,
        },
      })

      return { post, user: updatedUser }
    })

    const postWithUpdatedAuthor: PostWithAuthor = {
      ...result.post,
      author: {
        ...result.post.author,
        avatarUrl: category === 'avatar' ? displayUrl : result.post.author.avatarUrl,
      },
    }

    void enqueueContentAiScanForPost({
      id: result.post.id,
      authorId: result.post.authorId,
      title: result.post.title,
      body: result.post.body,
      mediaUrl: result.post.mediaUrl,
      images: result.post.images,
    }).catch((error) => {
      console.error('content_ai_scan_enqueue_profile_photo_post_failed', error)
    })

    return reply.send({
      ok: true,
      post: formatPost(postWithUpdatedAuthor),
      user: normalizeUserMedia(result.user),
    })
  }),
)

app.post('/media/uploads', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const authContext = await loadViewerAuthContext(req)
    if (!authContext) return reply.code(401).send({ error: 'unauthorized' })
    const ownerUserId = authContext.actor === 'family_member' ? authContext.member.parentId : authContext.userId

    const parse = RequestMediaUploadInput.safeParse(req.body)
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const { category, mime, byteSize, filename } = parse.data
    const mediaCategory = category as MediaCategory
    const limit = MEDIA_CATEGORY_LIMITS[mediaCategory]
    if (byteSize > limit) {
      return reply.code(400).send({ error: 'file_too_large', maxBytes: limit })
    }
    if (!ensureMimeSupported(mime)) {
      return reply.code(400).send({ error: 'unsupported_mime' })
    }

    const assetId = randomUUID()
    const extension = extensionForMime(mime)
    const originalKey = buildOriginalObjectKey(mediaCategory, ownerUserId, assetId, extension)
    const metadata = {
      ...(filename ? { filename } : {}),
      ...(authContext.actor === 'family_member' ? { familyMemberId: authContext.member.id } : {}),
    }

    const asset = await prisma.mediaAsset.create({
      data: {
        id: assetId,
        ownerId: ownerUserId,
        category: mediaCategory,
        assetType: 'image',
        storageType: 'minio',
        originalKey,
        mime,
        byteSize,
        status: 'pending',
        metadata,
      },
    })

    const command = new PutObjectCommand({
      Bucket: MEDIA_BUCKET_ORIGINAL,
      Key: originalKey,
      ContentType: mime,
    })
    const uploadUrl = await getSignedUrl(s3Client, command, { expiresIn: MEDIA_SIGNED_URL_TTL })
    const allowDirectUploadUrl = !isPrivateOrLocalNetworkUrl(uploadUrl)

    return reply.send({
      assetId: asset.id,
      upload: allowDirectUploadUrl
        ? {
            url: uploadUrl,
            method: 'PUT',
            headers: {
              'content-type': mime,
            },
          }
        : undefined,
      proxyPath: `/media/uploads/${asset.id}/proxy`,
      expiresInSeconds: MEDIA_SIGNED_URL_TTL,
      bucket: MEDIA_BUCKET_ORIGINAL,
      key: originalKey,
      maxBytes: limit,
    })
  }),
)

app.post('/media/uploads/complete', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const authContext = await loadViewerAuthContext(req)
    if (!authContext) return reply.code(401).send({ error: 'unauthorized' })
    const ownerUserId = authContext.actor === 'family_member' ? authContext.member.parentId : authContext.userId

    const parse = CompleteMediaUploadInput.safeParse(req.body)
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const { assetId, width, height, checksum } = parse.data
    const asset = await prisma.mediaAsset.findFirst({ where: { id: assetId, ownerId: ownerUserId } })
    if (!asset) return reply.code(404).send({ error: 'asset_not_found' })
    if (authContext.actor === 'family_member' && !familyMemberOwnsAssetForSession(asset, authContext.member.id)) {
      return reply.code(403).send({ error: 'asset_not_owned_by_family_member' })
    }

    if (asset.status === 'ready') {
      return reply.send({ ok: true, assetId })
    }

    const updatedAsset = await prisma.mediaAsset.update({
      where: { id: assetId },
      data: {
        width: width ?? asset.width,
        height: height ?? asset.height,
        checksum: checksum ?? asset.checksum,
        status: 'processing',
        failureReason: null,
      },
    })

    if (authContext.actor !== 'family_member') {
      if (asset.category === 'avatar') {
        await prisma.user.update({ where: { id: ownerUserId }, data: { avatarMediaId: updatedAsset.id } })
      } else if (asset.category === 'cover') {
        await prisma.user.update({ where: { id: ownerUserId }, data: { coverMediaId: updatedAsset.id } })
      }
    }

    await mediaQueue.add(
      'process',
      { assetId },
      {
        removeOnComplete: true,
        attempts: 5,
        backoff: { type: 'exponential', delay: 2000 },
      },
    )

    return reply.send({ ok: true, assetId })
  }),
)

app.put(
  '/media/uploads/:id/proxy',
  { bodyLimit: MEDIA_PROXY_UPLOAD_LIMIT },
  async (req: FastifyRequest, reply: FastifyReply) =>
    withSchemaGuard(req, reply, async () => {
      const authContext = await loadViewerAuthContext(req)
      if (!authContext) return reply.code(401).send({ error: 'unauthorized' })
      const ownerUserId = authContext.actor === 'family_member' ? authContext.member.parentId : authContext.userId

      const params = MediaAssetParam.safeParse(req.params)
      if (!params.success) return reply.code(400).send({ error: params.error.flatten() })

      const asset = await prisma.mediaAsset.findFirst({ where: { id: params.data.id, ownerId: ownerUserId } })
      if (!asset) return reply.code(404).send({ error: 'asset_not_found' })
      if (authContext.actor === 'family_member' && !familyMemberOwnsAssetForSession(asset, authContext.member.id)) {
        return reply.code(403).send({ error: 'asset_not_owned_by_family_member' })
      }
      if (asset.status !== 'pending') {
        return reply.code(409).send({ error: 'asset_not_pending' })
      }

      const bodyBuffer = Buffer.isBuffer((req as any).body) ? ((req as any).body as Buffer) : await readRequestBuffer(req)
      if (!bodyBuffer || bodyBuffer.length === 0) {
        return reply.code(400).send({ error: 'empty_upload' })
      }

      const assetCategory = asset.category as MediaCategory
      const maxBytes = asset.byteSize ?? MEDIA_CATEGORY_LIMITS[assetCategory]
      if (maxBytes && bodyBuffer.length > maxBytes) {
        return reply.code(400).send({ error: 'file_too_large', maxBytes })
      }

      await s3Client.send(
        new PutObjectCommand({
          Bucket: MEDIA_BUCKET_ORIGINAL,
          Key: asset.originalKey,
          Body: bodyBuffer,
          ContentType: asset.mime ?? 'application/octet-stream',
        }),
      )

      return reply.send({ ok: true, bytesUploaded: bodyBuffer.length })
    }),
)

