const VotePostInput = z.object({
  postId: z.string().cuid(),
  value: z.union([z.literal(-1), z.literal(0), z.literal(1)]),
})

app.post('/posts/vote', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const userId = (req as any).user?.id as string | undefined
    if (!userId) return reply.code(401).send({ error: 'unauthorized' })

    const parse = VotePostInput.safeParse(req.body ?? {})
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const { postId, value } = parse.data

    const post = await prisma.post.findUnique({
      where: { id: postId },
      select: { id: true, authorId: true, createdAt: true, updatedAt: true, visibility: true, businessId: true, moderationStatus: true },
    })
    if (!post) return reply.code(404).send({ error: 'post_not_found' })
    if (post.moderationStatus !== ModerationStatus.VISIBLE) {
      return reply.code(423).send({ error: moderationLockedErrorCode('POST') })
    }

    if (post.visibility === 'members' && post.businessId) {
      const business = await prisma.business.findUnique({
        where: { id: post.businessId },
        select: { ownerId: true, moderationStatus: true },
      })
      if (!business || business.moderationStatus !== ModerationStatus.VISIBLE) {
        return reply.code(423).send({ error: moderationLockedErrorCode('ORGANIZATION') })
      }
      const isOwner = business?.ownerId === userId
      const membership = isOwner
        ? { role: 'OWNER' as const }
        : await prisma.businessMembership.findUnique({
            where: { businessId_userId: { businessId: post.businessId, userId } },
            select: { role: true },
          })
      if (!membership) return reply.code(404).send({ error: 'post_not_found' })
    }

    const mappedReaction: PrismaReactionType | null =
      value === 1 ? PrismaReactionType.maple : value === -1 ? PrismaReactionType.sad : null

    await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
      // Legacy votes are deprecated in favor of reactions.
      await tx.vote.deleteMany({
        where: {
          userId,
          postId,
        },
      })

      if (!mappedReaction) {
        await tx.postReaction.deleteMany({
          where: {
            userId,
            postId,
          },
        })
      } else {
        await tx.postReaction.upsert({
          where: {
            userId_postId: {
              userId,
              postId,
            },
          },
          create: {
            userId,
            postId,
            type: mappedReaction,
          },
          update: {
            type: mappedReaction,
          },
        })
      }

      await refreshPostAggregates(tx, postId, { createdAt: post.createdAt, lastActivityAt: post.updatedAt }, { bumpActivity: false })
    })

    const updatedPost = await prisma.post.findUnique({
      where: { id: postId },
      include: POST_INCLUDE,
    })

    if (!updatedPost) return reply.code(404).send({ error: 'post_not_found' })
    const { pollSelectionsByPost, recentCommentsByPost } = await loadViewerPostFormattingContext(userId, [postId], 5)

    return reply.send({
      post: formatPost(updatedPost, {
        viewerId: userId,
        viewerReaction: mappedReaction,
        viewerPollOptionId: pollSelectionsByPost[postId] ?? null,
        recentComments: recentCommentsByPost[postId] ?? [],
      }),
    })
  }),
)

app.post('/posts/react', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const userId = (req as any).user?.id as string | undefined
    if (!userId) return reply.code(401).send({ error: 'unauthorized' })

    const parse = ReactPostInput.safeParse(req.body ?? {})
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const { postId, reaction } = parse.data

    const post = await prisma.post.findUnique({
      where: { id: postId },
      select: { id: true, authorId: true, createdAt: true, updatedAt: true, visibility: true, businessId: true, moderationStatus: true },
    })
    if (!post) return reply.code(404).send({ error: 'post_not_found' })
    if (post.moderationStatus !== ModerationStatus.VISIBLE) {
      return reply.code(423).send({ error: moderationLockedErrorCode('POST') })
    }

    if (post.visibility === 'members' && post.businessId) {
      const business = await prisma.business.findUnique({
        where: { id: post.businessId },
        select: { ownerId: true, moderationStatus: true },
      })
      if (!business || business.moderationStatus !== ModerationStatus.VISIBLE) {
        return reply.code(423).send({ error: moderationLockedErrorCode('ORGANIZATION') })
      }
      const isOwner = business?.ownerId === userId
      const membership = isOwner
        ? { role: 'OWNER' as const }
        : await prisma.businessMembership.findUnique({
            where: { businessId_userId: { businessId: post.businessId, userId } },
            select: { role: true },
          })
      if (!membership) return reply.code(404).send({ error: 'post_not_found' })
    }

    const normalizedReaction: PrismaReactionType | null =
      reaction === null
        ? null
        : reaction === 'maple'
          ? PrismaReactionType.maple
          : reaction === 'heart'
            ? PrismaReactionType.heart
            : reaction === 'haha'
              ? PrismaReactionType.haha
              : reaction === 'wow'
                ? PrismaReactionType.wow
                : reaction === 'sad'
                  ? PrismaReactionType.sad
                  : reaction === 'fire'
                    ? PrismaReactionType.fire
                    : null

    if (reaction !== null && !normalizedReaction) {
      return reply.code(400).send({ error: 'invalid_reaction' })
    }

    await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
      await tx.vote.deleteMany({
        where: {
          userId,
          postId,
        },
      })

      if (!normalizedReaction) {
        await tx.postReaction.deleteMany({
          where: {
            userId,
            postId,
          },
        })
      } else {
        await tx.postReaction.upsert({
          where: {
            userId_postId: {
              userId,
              postId,
            },
          },
          create: {
            userId,
            postId,
            type: normalizedReaction,
          },
          update: {
            type: normalizedReaction,
          },
        })
      }

      await refreshPostAggregates(tx, postId, { createdAt: post.createdAt, lastActivityAt: post.updatedAt }, { bumpActivity: false })
    })

    const updatedPost = await prisma.post.findUnique({
      where: { id: postId },
      include: POST_INCLUDE,
    })

    if (!updatedPost) return reply.code(404).send({ error: 'post_not_found' })
    const { pollSelectionsByPost, recentCommentsByPost } = await loadViewerPostFormattingContext(userId, [postId], 5)

    return reply.send({
      post: formatPost(updatedPost, {
        viewerId: userId,
        viewerReaction: normalizedReaction,
        viewerPollOptionId: pollSelectionsByPost[postId] ?? null,
        recentComments: recentCommentsByPost[postId] ?? [],
      }),
    })
  }),
)

app.get('/posts/:id/comments', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const params = z.object({ id: z.string().cuid() }).safeParse(req.params)
    if (!params.success) return reply.code(400).send({ error: 'invalid_id' })

    const query = z.object({ sort: CommentSortEnum.optional() }).safeParse(req.query ?? {})
    if (!query.success) return reply.code(400).send({ error: query.error.flatten() })

    const post = await prisma.post.findUnique({
      where: { id: params.data.id },
      select: { id: true, visibility: true, businessId: true, moderationStatus: true, authorId: true },
    })
    if (!post) return reply.code(404).send({ error: 'post_not_found' })

    const viewerId = (req as any).user?.id as string | undefined
    const blockState = await loadViewerBlockState(viewerId)
    if (isPostHiddenFromViewer(post, blockState)) return reply.code(404).send({ error: 'post_not_found' })

    if (post.visibility === 'members' && post.businessId) {
      if (!viewerId) return reply.code(404).send({ error: 'post_not_found' })
      const business = await prisma.business.findUnique({
        where: { id: post.businessId },
        select: { ownerId: true, moderationStatus: true },
      })
      if (!business || business.moderationStatus !== ModerationStatus.VISIBLE) {
        return reply.code(423).send({ error: moderationLockedErrorCode('ORGANIZATION') })
      }
      const isOwner = business?.ownerId === viewerId
      const membership = isOwner
        ? { role: 'OWNER' as const }
        : await prisma.businessMembership.findUnique({
            where: { businessId_userId: { businessId: post.businessId, userId: viewerId } },
            select: { role: true },
          })
      if (!membership) return reply.code(404).send({ error: 'post_not_found' })
    }

    const sortMode = query.data.sort ?? 'hot'

    const commentRows: CommentWithUser[] = await prisma.comment.findMany({
      where: { postId: params.data.id, moderationStatus: ModerationStatus.VISIBLE },
      orderBy: { createdAt: 'asc' },
      include: {
        user: {
          select: {
            id: true,
            handle: true,
            name: true,
            avatarUrl: true,
            coverUrl: true,
            premiumStatus: true,
          },
        },
      },
    })

    let viewerCommentVotes: Record<string, number> = {}
    if (viewerId && commentRows.length) {
      const commentIds = commentRows.map((comment) => comment.id)
      const votes = await prisma.commentVote.findMany({
        where: { userId: viewerId, commentId: { in: commentIds } },
        select: { commentId: true, value: true },
      })
      const voteMap: Record<string, number> = {}
      for (const vote of votes) {
        voteMap[vote.commentId] = vote.value
      }
      viewerCommentVotes = voteMap
    }

    const visibleCommentRows = filterCommentRowsForViewer(commentRows, blockState)

    return reply.send({
      comments: buildCommentTree(visibleCommentRows, viewerCommentVotes, { sort: sortMode }),
    })
  }),
)

app.post('/comments', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const userId = (req as any).user?.id as string | undefined
    if (!userId) return reply.code(401).send({ error: 'unauthorized' })

    const parse = CreateCommentInput.safeParse(req.body ?? {})
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const { postId, body: rawBody, parentId } = parse.data
    const body = sanitizePlainText(rawBody)

    const user = await prisma.user.findUnique({ where: { id: userId }, select: { id: true } })
    if (!user) {
      return reply.code(404).send({ error: 'user_not_found' })
    }

    const post = await prisma.post.findUnique({
      where: { id: postId },
      select: { id: true, authorId: true, createdAt: true, updatedAt: true, visibility: true, businessId: true, moderationStatus: true },
    })
    if (!post) return reply.code(404).send({ error: 'post_not_found' })
    if (post.moderationStatus !== ModerationStatus.VISIBLE) {
      return reply.code(423).send({ error: moderationLockedErrorCode('POST') })
    }

    if (post.visibility === 'members' && post.businessId) {
      const business = await prisma.business.findUnique({
        where: { id: post.businessId },
        select: { ownerId: true, moderationStatus: true },
      })
      if (!business || business.moderationStatus !== ModerationStatus.VISIBLE) {
        return reply.code(423).send({ error: moderationLockedErrorCode('ORGANIZATION') })
      }
      const isOwner = business?.ownerId === userId
      const membership = isOwner
        ? { role: 'OWNER' as const }
        : await prisma.businessMembership.findUnique({
            where: { businessId_userId: { businessId: post.businessId, userId } },
            select: { role: true },
          })
      if (!membership) return reply.code(404).send({ error: 'post_not_found' })
    }

    let parentComment: { id: string; postId: string; userId: string } | null = null
    if (parentId) {
      const parent = await prisma.comment.findUnique({
        where: { id: parentId },
        select: { id: true, postId: true, userId: true, moderationStatus: true },
      })
      if (!parent || parent.postId !== postId || parent.moderationStatus !== ModerationStatus.VISIBLE) {
        return reply.code(400).send({ error: 'invalid_parent_comment' })
      }
      parentComment = parent
    }

    const created = await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
      const comment = await tx.comment.create({
        data: {
          postId,
          userId,
          parentId: parentId ?? null,
          body,
        },
        include: {
          user: {
            select: {
              id: true,
              handle: true,
              name: true,
              avatarUrl: true,
              coverUrl: true,
              premiumStatus: true,
            },
          },
        },
      })

      await refreshPostAggregates(tx, postId, { createdAt: post.createdAt, lastActivityAt: post.updatedAt }, { bumpActivity: true })

      return comment
    })

    const updatedPost = await prisma.post.findUnique({
      where: { id: postId },
      include: POST_INCLUDE,
    })

    if (parentComment && parentComment.userId !== userId && updatedPost) {
      const paths = getCanonicalPaths(updatedPost)
      const basePath = paths.community ?? paths.user
      const sourceCommentTarget = `${basePath}?comment=${encodeURIComponent(parentComment.id)}#comment-${parentComment.id}`
      const replyCommentTarget = `${basePath}?comment=${encodeURIComponent(created.id)}#comment-${created.id}`
      await createNotificationRecord({
        userId: parentComment.userId,
        actorId: userId,
        type: COMMENT_NOTIFICATION_TYPES.REPLY,
        postId,
        payload: {
          commentId: created.id,
          parentCommentId: parentComment.id,
          bodyPreview: truncatePushBody(body, 90),
          url: sourceCommentTarget,
          sourceUrl: sourceCommentTarget,
          replyUrl: replyCommentTarget,
        },
      })
    }

    if (!parentComment && post.authorId && post.authorId !== userId && updatedPost) {
      const paths = getCanonicalPaths(updatedPost)
      const basePath = paths.community ?? paths.user
      const commentTarget = `${basePath}?comment=${encodeURIComponent(created.id)}#comment-${created.id}`
      await createNotificationRecord({
        userId: post.authorId,
        actorId: userId,
        type: COMMENT_NOTIFICATION_TYPES.POST_COMMENT,
        postId,
        payload: {
          commentId: created.id,
          bodyPreview: truncatePushBody(body, 90),
          url: commentTarget,
          sourceUrl: commentTarget,
        },
      })
    }

    const formattingContext = updatedPost ? await loadViewerPostFormattingContext(userId, [updatedPost.id], 5) : null

    void enqueueContentAiScanForComment(created).catch((error) => {
      console.error('content_ai_scan_enqueue_comment_failed', error)
    })

    return reply.code(201).send({
      comment: {
        ...mapComment(created, 0),
        createdAt: created.createdAt.toISOString(),
        updatedAt: created.updatedAt.toISOString(),
      },
      post: updatedPost
        ? formatPost(updatedPost, {
            viewerId: userId,
            viewerReaction: formattingContext?.reactionsByPost[updatedPost.id] ?? null,
            viewerPollOptionId: formattingContext?.pollSelectionsByPost[updatedPost.id] ?? null,
            recentComments: formattingContext?.recentCommentsByPost[updatedPost.id] ?? [],
          })
        : null,
    })
  }),
)

app.post('/comments/vote', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const userId = (req as any).user?.id as string | undefined
    if (!userId) return reply.code(401).send({ error: 'unauthorized' })

    const parse = VoteCommentInput.safeParse(req.body ?? {})
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const user = await prisma.user.findUnique({ where: { id: userId }, select: { id: true } })
    if (!user) {
      return reply.code(404).send({ error: 'user_not_found' })
    }

    const { commentId, value } = parse.data
    const existing = await prisma.comment.findUnique({
      where: { id: commentId },
      include: {
        user: {
          select: {
            id: true,
            handle: true,
            name: true,
            avatarUrl: true,
            coverUrl: true,
            premiumStatus: true,
          },
        },
        post: {
          select: { id: true, createdAt: true, updatedAt: true, visibility: true, businessId: true, moderationStatus: true },
        },
      },
    })

    if (!existing) return reply.code(404).send({ error: 'comment_not_found' })
    if (existing.moderationStatus !== ModerationStatus.VISIBLE) {
      return reply.code(423).send({ error: moderationLockedErrorCode('COMMENT') })
    }
    if (existing.post.moderationStatus !== ModerationStatus.VISIBLE) {
      return reply.code(423).send({ error: moderationLockedErrorCode('POST') })
    }

    if (existing.post.visibility === 'members' && existing.post.businessId) {
      const business = await prisma.business.findUnique({
        where: { id: existing.post.businessId },
        select: { ownerId: true, moderationStatus: true },
      })
      if (!business || business.moderationStatus !== ModerationStatus.VISIBLE) {
        return reply.code(423).send({ error: moderationLockedErrorCode('ORGANIZATION') })
      }
      const isOwner = business?.ownerId === userId
      const membership = isOwner
        ? { role: 'OWNER' as const }
        : await prisma.businessMembership.findUnique({
            where: { businessId_userId: { businessId: existing.post.businessId, userId } },
            select: { role: true },
          })
      if (!membership) return reply.code(404).send({ error: 'comment_not_found' })
    }

    const result = await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
      if (value === 0) {
        await tx.commentVote.deleteMany({
          where: {
            userId,
            commentId,
          },
        })
      } else {
        await tx.commentVote.upsert({
          where: {
            userId_commentId: {
              userId,
              commentId,
            },
          },
          create: {
            userId,
            commentId,
            value,
          },
          update: {
            value,
          },
        })
      }

      await refreshCommentAggregates(tx, commentId)
      await refreshPostAggregates(tx, existing.postId, { createdAt: existing.post.createdAt, lastActivityAt: existing.post.updatedAt }, { bumpActivity: false })

      const updatedComment = await tx.comment.findUnique({
        where: { id: commentId },
        include: {
          user: {
            select: {
              id: true,
              handle: true,
              name: true,
              avatarUrl: true,
              coverUrl: true,
              premiumStatus: true,
            },
          },
        },
      })

      return updatedComment
    })

    if (!result) return reply.code(404).send({ error: 'comment_not_found' })

    return reply.send({
      comment: {
        ...mapComment(result, value),
        createdAt: result.createdAt.toISOString(),
        updatedAt: result.updatedAt.toISOString(),
      },
    })
  }),
)

app.delete('/posts/:id', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const userId = (req as any).user?.id
    if (!userId) return reply.code(401).send({ error: 'unauthorized' })

    const params = z.object({ id: z.string().cuid() }).safeParse(req.params)
    if (!params.success) return reply.code(400).send({ error: 'invalid_id' })

    const post = await prisma.post.findUnique({
      where: { id: params.data.id },
      select: { authorId: true, type: true, moderationStatus: true },
    })
    if (!post) return reply.code(404).send({ error: 'post_not_found' })
    if (post.moderationStatus !== ModerationStatus.VISIBLE) {
      return reply.code(423).send({ error: moderationLockedErrorCode('POST') })
    }

    if (post.authorId !== userId) {
      return reply.code(403).send({ error: 'forbidden' })
    }

    await prisma.post.delete({ where: { id: params.data.id } })

    return reply.send({ success: true })
  }),
)

app.patch('/posts/:id', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const userId = (req as any).user?.id
    if (!userId) return reply.code(401).send({ error: 'unauthorized' })

    const params = z.object({ id: z.string().cuid() }).safeParse(req.params)
    if (!params.success) return reply.code(400).send({ error: 'invalid_id' })

    const parse = UpdatePostInput.safeParse(req.body)
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const post = await prisma.post.findUnique({
      where: { id: params.data.id },
      select: {
        authorId: true,
        businessId: true,
        type: true,
        moderationStatus: true,
        poll: {
          select: {
            endedAt: true,
            _count: {
              select: {
                votes: true,
              },
            },
          },
        },
      },
    })
    if (!post) return reply.code(404).send({ error: 'post_not_found' })
    if (post.moderationStatus !== ModerationStatus.VISIBLE) {
      return reply.code(423).send({ error: moderationLockedErrorCode('POST') })
    }

    if (post.authorId !== userId) {
      return reply.code(403).send({ error: 'forbidden' })
    }

    const { title, body: rawBody, mediaUrl, hashtags, showBusinessAuthor } = parse.data
    if (post.type === 'poll') {
      if (post.poll?.endedAt) {
        return reply.code(409).send({ error: 'poll_closed' })
      }
      if ((post.poll?._count.votes ?? 0) > 0 && rawBody !== undefined) {
        return reply.code(409).send({ error: 'poll_locked' })
      }
      if (title !== undefined || mediaUrl !== undefined) {
        return reply.code(400).send({ error: 'poll_update_not_supported' })
      }
    }

    const updated = await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
      const postData: Prisma.PostUpdateInput = {}
      if (title !== undefined) {
        postData.title = title
      }
      if (rawBody !== undefined) {
        postData.body = post.type === 'article' ? sanitizeRichTextHtml(rawBody) : sanitizePlainText(rawBody)
      }
      if (mediaUrl !== undefined) {
        postData.mediaUrl = mediaUrl
      }
      if (showBusinessAuthor !== undefined) {
        postData.showBusinessAuthor = Boolean(post.businessId && showBusinessAuthor)
      }

      const updatedPost = await tx.post.update({
        where: { id: params.data.id },
        data: postData,
        include: POST_INCLUDE,
      })

      if (hashtags) {
        // Clear existing hashtags
        await tx.postHashtag.deleteMany({ where: { postId: params.data.id } })

        const tags = [...new Set(hashtags.map((t: string) => t.replace(/^#/, '')))] as string[]
        if (tags.length) {
          await tx.hashtag.createMany({ data: tags.map((tag: string) => ({ tag })), skipDuplicates: true })
          await tx.postHashtag.createMany({ data: tags.map((tag: string) => ({ postId: params.data.id, tag })) })
        }
      }

      return updatedPost
    })

    const { reactionsByPost, pollSelectionsByPost, recentCommentsByPost } = await loadViewerPostFormattingContext(userId, [params.data.id], 5)

    void enqueueContentAiScanForPost({
      id: updated.id,
      authorId: updated.authorId,
      title: updated.title ?? null,
      body: updated.body,
      mediaUrl: updated.mediaUrl ?? null,
      images: updated.images,
    }).catch((error) => {
      console.error('content_ai_scan_enqueue_post_update_failed', error)
    })

    return reply.send(
      formatPost(updated, {
        viewerId: userId,
        viewerReaction: reactionsByPost[params.data.id] ?? null,
        viewerPollOptionId: pollSelectionsByPost[params.data.id] ?? null,
        recentComments: recentCommentsByPost[params.data.id] ?? [],
      }),
    )
  }),
)

// Auth: login
app.post('/auth/login', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const parse = LoginInput.safeParse(req.body)
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })
    const { emailOrHandle, password } = parse.data
    const rawIdentifier = emailOrHandle.trim()
    const identifier = rawIdentifier.startsWith('@') ? rawIdentifier.slice(1) : rawIdentifier

    const user = await prisma.user.findFirst({
      where: {
        OR: [
          { email: { equals: identifier, mode: 'insensitive' } },
          { handle: { equals: identifier, mode: 'insensitive' } },
        ],
      },
    })
    if (!user) return reply.code(401).send({ error: 'invalid_credentials' })
    if (isAccountSuspended(user.communityMeta)) return reply.code(403).send({ error: 'account_suspended' })
    const ok = await bcrypt.compare(password, (user as any).passwordHash)
    if (!ok) return reply.code(401).send({ error: 'invalid_credentials' })
    await prisma.user.update({ where: { id: user.id }, data: { lastLoginAt: new Date() } })
    const token = await (app as any).jwt.sign({ sub: user.id })
    return reply.send({ token, user: { id: user.id, email: user.email, handle: user.handle, name: user.name } })
  }),
)

// Auth: me
app.get('/auth/me', async (req: FastifyRequest, reply: FastifyReply) => {
  try {
    const payload = (await (req as any).jwtVerify()) as AuthJwtPayload
    if (!payload?.sub || typeof payload.sub !== 'string') {
      return reply.code(401).send({ error: 'unauthorized' })
    }

    if (payload.actor === 'family_member') {
      const member = await loadFamilyMemberAuthViewerById(payload.sub, payload.parentId ?? null)
      if (!member) return reply.code(401).send({ error: 'unauthorized' })

      const homeCommunity = await buildHomeCommunitySummaryForUserId(member.parentId)
      return reply.send(buildFamilyMemberAuthMeResponse(member, homeCommunity))
    }

    const user = await prisma.user.findUnique({
      where: { id: payload.sub },
      select: {
        id: true,
        email: true,
        handle: true,
        name: true,
        avatarUrl: true,
        coverUrl: true,
        communityMeta: true,
        premiumStatus: true,
        premiumSince: true,
        premiumRenewsAt: true,
      },
    })
    if (!user) return reply.code(401).send({ error: 'unauthorized' })
    if (isAccountSuspended(user.communityMeta)) return reply.code(403).send({ error: 'account_suspended' })

    const homeCommunity = await buildHomeCommunitySummaryForUserId(payload.sub)

    const normalizedUser = normalizeUserMedia(user)
    const communityMeta = parseCommunityMeta(user.communityMeta ?? null)
    let familyMemberCount = 0
    try {
      familyMemberCount = await prisma.familyMember.count({ where: { parentId: payload.sub } })
    } catch (error) {
      if (!isFamilyMemberTableMissing(error)) throw error
    }
    return reply.send({
      ...normalizedUser,
      homeCommunity,
      isPremium: isPremium(user.premiumStatus),
      isVerified: isSelfVerifiedCanadianCitizen(communityMeta),
      premiumSince: user.premiumSince ?? null,
      premiumRenewsAt: user.premiumRenewsAt ?? null,
      civicStatus: communityMeta?.civicStatus ?? null,
      workAuthorization: communityMeta?.workAuthorization ?? null,
      verificationMethod: communityMeta?.verificationMethod ?? null,
      statusDeclaredAt: communityMeta?.statusDeclaredAt ?? null,
      statusUpdatedAt: communityMeta?.statusUpdatedAt ?? null,
      familyMode: {
        enabled: Boolean(communityMeta?.familyMode?.enabledAt),
        enabledAt: communityMeta?.familyMode?.enabledAt ?? null,
        affirmedProfileTruthAt: communityMeta?.familyMode?.affirmedProfileTruthAt ?? null,
        acceptedChildSafetyInfoAt: communityMeta?.familyMode?.acceptedChildSafetyInfoAt ?? null,
        memberCount: familyMemberCount,
      },
      accountType: 'user',
      familyMemberSession: null,
    })
  } catch {
    return reply.code(401).send({ error: 'unauthorized' })
  }
})

app.post('/auth/status-declaration', async (req: FastifyRequest, reply: FastifyReply) => {
  try {
    const payload = await (req as any).jwtVerify()
    const body = UpdateCivilStatusBody.safeParse(req.body ?? {})
    if (!body.success) return reply.code(400).send({ error: body.error.flatten() })

    const user = await prisma.user.findUnique({ where: { id: payload.sub }, select: { communityMeta: true } })
    if (!user) return reply.code(401).send({ error: 'unauthorized' })
  if (isAccountSuspended(user.communityMeta)) return reply.code(403).send({ error: 'account_suspended' })

    const baseMeta = readBaseCommunityMeta(user.communityMeta)
    const currentMeta = parseCommunityMeta(user.communityMeta ?? null)
    const nowIso = new Date().toISOString()
    const workAuthorization =
      body.data.civicStatus === 'citizen' || body.data.civicStatus === 'permanent_resident'
        ? 'authorized'
        : body.data.workAuthorization ?? 'unspecified'

    baseMeta.civicStatus = body.data.civicStatus
    baseMeta.workAuthorization = workAuthorization
    baseMeta.verificationMethod = 'self_declaration'
    baseMeta.statusDeclaredAt = currentMeta?.statusDeclaredAt ?? nowIso
    baseMeta.statusUpdatedAt = nowIso

    await prisma.user.update({ where: { id: payload.sub }, data: { communityMeta: baseMeta } })

    return reply.send({
      civicStatus: body.data.civicStatus,
      workAuthorization,
      verificationMethod: 'self_declaration',
      statusDeclaredAt: currentMeta?.statusDeclaredAt ?? nowIso,
      statusUpdatedAt: nowIso,
    })
  } catch {
    return reply.code(401).send({ error: 'unauthorized' })
  }
})

