app.get('/messages/threads/:id', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const authContext = await loadViewerAuthContext(req)
    if (!authContext) return reply.code(401).send({ error: 'unauthorized' })

    const userId = authContext.actor === 'family_member' ? authContext.member.parentId : authContext.userId

    const params = MessageThreadIdParam.safeParse(req.params)
    if (!params.success) return reply.code(400).send({ error: params.error.flatten() })

    if (authContext.actor === 'user' && isParentFamilyThreadId(params.data.id)) {
      const memberId = parseParentFamilyThreadId(params.data.id)
      if (!memberId) return reply.code(404).send({ error: 'thread_not_found' })
      const query = MessageListQuery.safeParse(req.query ?? {})
      if (!query.success) return reply.code(400).send({ error: query.error.flatten() })
      const context = await loadParentFamilyConversationContext(authContext.userId, memberId)
      if (!context) return reply.code(404).send({ error: 'thread_not_found' })
      const { rows, nextCursor } = fetchParentFamilyConversationMessages(
        context.member,
        context.parent,
        context.conversation,
        query.data.limit,
        query.data.cursor,
      )
      return reply.send({
        thread: buildParentFamilyConversationThread(context),
        messages: rows,
        nextCursor,
      })
    }

    if (authContext.actor === 'family_member' && params.data.id === buildFamilyParentThreadId(authContext.member.parentId)) {
      const query = MessageListQuery.safeParse(req.query ?? {})
      if (!query.success) return reply.code(400).send({ error: query.error.flatten() })
      const conversation =
        getFamilyParentConversation(
          authContext.member.parent.communityMeta,
          authContext.member.id,
          authContext.member.parentId,
        ) ?? null
      const { rows, nextCursor } = fetchFamilyParentConversationMessages(
        authContext.member,
        conversation,
        query.data.limit,
        query.data.cursor,
      )
      return reply.send({
        thread: buildFamilyParentConversationThread(authContext.member, conversation),
        messages: rows,
        nextCursor,
      })
    }

    if (authContext.actor === 'family_member' && !familyMemberCanAccessMessageThread(authContext.member, params.data.id)) {
      return reply.code(404).send({ error: 'thread_not_found' })
    }

    const thread = await loadThreadForUser(params.data.id, userId)
    if (!thread) return reply.code(404).send({ error: 'thread_not_found' })

    const query = MessageListQuery.safeParse(req.query ?? {})
    if (!query.success) return reply.code(400).send({ error: query.error.flatten() })

    const { rows, nextCursor } = await fetchThreadMessages(thread.id, query.data.limit, query.data.cursor)

    return reply.send({
      thread: formatThreadBase(thread, userId),
      messages: rows.map((message: MessageRecord) => formatMessage(message, userId)),
      nextCursor,
    })
  }),
)

app.get('/messages/threads/:id/messages', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const authContext = await loadViewerAuthContext(req)
    if (!authContext) return reply.code(401).send({ error: 'unauthorized' })

    const userId = authContext.actor === 'family_member' ? authContext.member.parentId : authContext.userId

    const params = MessageThreadIdParam.safeParse(req.params)
    if (!params.success) return reply.code(400).send({ error: params.error.flatten() })

    if (authContext.actor === 'user' && isParentFamilyThreadId(params.data.id)) {
      const memberId = parseParentFamilyThreadId(params.data.id)
      if (!memberId) return reply.code(404).send({ error: 'thread_not_found' })
      const query = MessageListQuery.safeParse(req.query ?? {})
      if (!query.success) return reply.code(400).send({ error: query.error.flatten() })
      const context = await loadParentFamilyConversationContext(authContext.userId, memberId)
      if (!context) return reply.code(404).send({ error: 'thread_not_found' })
      const { rows, nextCursor } = fetchParentFamilyConversationMessages(
        context.member,
        context.parent,
        context.conversation,
        query.data.limit,
        query.data.cursor,
      )
      return reply.send({ items: rows, nextCursor })
    }

    if (authContext.actor === 'family_member' && params.data.id === buildFamilyParentThreadId(authContext.member.parentId)) {
      const query = MessageListQuery.safeParse(req.query ?? {})
      if (!query.success) return reply.code(400).send({ error: query.error.flatten() })
      const conversation =
        getFamilyParentConversation(
          authContext.member.parent.communityMeta,
          authContext.member.id,
          authContext.member.parentId,
        ) ?? null
      const { rows, nextCursor } = fetchFamilyParentConversationMessages(
        authContext.member,
        conversation,
        query.data.limit,
        query.data.cursor,
      )
      return reply.send({
        items: rows,
        nextCursor,
      })
    }

    if (authContext.actor === 'family_member' && !familyMemberCanAccessMessageThread(authContext.member, params.data.id)) {
      return reply.code(404).send({ error: 'thread_not_found' })
    }

    const membership = await prisma.messageParticipant.findUnique({
      where: {
        threadId_userId: {
          threadId: params.data.id,
          userId,
        },
        thread: {
          OR: [{ contextType: null }, { contextType: { not: 'market_listing' } }],
        },
      },
      select: { threadId: true },
    })
    if (!membership) return reply.code(404).send({ error: 'thread_not_found' })

    const query = MessageListQuery.safeParse(req.query ?? {})
    if (!query.success) return reply.code(400).send({ error: query.error.flatten() })

    const { rows, nextCursor } = await fetchThreadMessages(params.data.id, query.data.limit, query.data.cursor)

    return reply.send({
      items: rows.map((message: MessageRecord) => formatMessage(message, userId)),
      nextCursor,
    })
  }),
)

app.post('/messages/threads/:id/messages', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const authContext = await loadViewerAuthContext(req)
    if (!authContext) return reply.code(401).send({ error: 'unauthorized' })

    const userId = authContext.actor === 'family_member' ? authContext.member.parentId : authContext.userId

    const params = MessageThreadIdParam.safeParse(req.params)
    if (!params.success) return reply.code(400).send({ error: params.error.flatten() })

    const parse = SendMessageInput.safeParse(req.body ?? {})
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    if (authContext.actor === 'user' && isParentFamilyThreadId(params.data.id)) {
      const memberId = parseParentFamilyThreadId(params.data.id)
      if (!memberId) return reply.code(404).send({ error: 'thread_not_found' })
      const normalizedBody = parse.data.body?.trim() ? sanitizePlainText(parse.data.body) : ''
      if (!normalizedBody) return reply.code(400).send({ error: 'message_body_required' })
      const context = await loadParentFamilyConversationContext(authContext.userId, memberId)
      if (!context) return reply.code(404).send({ error: 'thread_not_found' })
      const conversation = await storeFamilyParentConversationMessage({
        parentId: authContext.userId,
        memberId,
        sender: 'parent',
        body: normalizedBody,
      })
      const message = formatParentFamilyConversationMessage(conversation, context.member, context.parent).at(-1)
      const thread = buildParentFamilyConversationThread({
        parent: context.parent,
        member: context.member,
        conversation,
      })
      if (!message) return reply.code(500).send({ error: 'message_create_failed' })

      await Promise.all([
        dispatchRealtimeEvent(authContext.userId, {
          type: 'thread.created',
          data: { thread },
        }),
        dispatchRealtimeEvent(authContext.userId, {
          type: 'message.created',
          data: { threadId: thread.id, message },
        }),
      ])

      return reply.code(201).send({ message })
    }

    if (authContext.actor === 'family_member' && params.data.id === buildFamilyParentThreadId(authContext.member.parentId)) {
      const normalizedBody = parse.data.body?.trim() ? sanitizePlainText(parse.data.body) : ''
      if (!normalizedBody) return reply.code(400).send({ error: 'message_body_required' })
      const conversation = await storeFamilyParentConversationMessage({
        parentId: authContext.member.parentId,
        memberId: authContext.member.id,
        sender: 'child',
        body: normalizedBody,
      })
      const message = formatFamilyParentConversationMessage(conversation, authContext.member).at(-1)
      const thread = buildFamilyParentConversationThread(authContext.member, conversation)
      if (!message) return reply.code(500).send({ error: 'message_create_failed' })

      await Promise.all([
        dispatchRealtimeEvent(authContext.member.parentId, {
          type: 'thread.created',
          data: {
            thread: await (async () => {
              const context = await loadParentFamilyConversationContext(authContext.member.parentId, authContext.member.id)
              return context ? buildParentFamilyConversationThread(context) : null
            })(),
          },
        }),
        dispatchRealtimeEvent(authContext.member.parentId, {
          type: 'message.created',
          data: {
            threadId: buildParentFamilyThreadId(authContext.member.id),
            message: await (async () => {
              const context = await loadParentFamilyConversationContext(authContext.member.parentId, authContext.member.id)
              if (!context) return null
              return formatParentFamilyConversationMessage(conversation, context.member, context.parent).at(-1) ?? null
            })(),
          },
        }),
        dispatchRealtimeEvent(authContext.member.parentId, {
          type: 'thread.updated',
          data: {
            thread: await (async () => {
              const context = await loadParentFamilyConversationContext(authContext.member.parentId, authContext.member.id)
              return context ? buildParentFamilyConversationThread(context) : null
            })(),
          },
        }),
      ])

      void (async () => {
        const threadId = buildParentFamilyThreadId(authContext.member.id)
        const sender = formatNormalizedFamilyMemberThreadUser(normalizeFamilyMemberSummary(authContext.member))
        const rawSenderLabel = sender.name || sender.handle || 'Someone'
        const title = formatDisplayNameForPush(rawSenderLabel) || rawSenderLabel
        const body = truncatePushBody(normalizedBody)
        const pushUrl = `/messages?inbox=family&thread=${encodeURIComponent(threadId)}`
        if (!body) return

        await sendPushToUser(authContext.member.parentId, {
          title,
          body,
          url: pushUrl,
          type: 'message',
          entityId: threadId,
        }).catch(() => undefined)

        if (!PUSH_DELIVERY_URL) return
        const deviceTargets = await loadActiveNativePushTargets(authContext.member.parentId)
        if (!deviceTargets.length) return
        const badge = await loadUnreadMessageCount(authContext.member.parentId)
        await Promise.allSettled(
          deviceTargets.map(({ platform, token }) =>
            deliverNativePushToToken({
              platform,
              deviceToken: token,
              title,
              message: body,
              badge,
              sound: 'civil-message.caf',
              data: {
                kind: 'message',
                threadId,
                url: pushUrl,
              },
            }),
          ),
        )
      })()

      return reply.code(201).send({ message })
    }

    if (authContext.actor === 'family_member' && !familyMemberCanAccessMessageThread(authContext.member, params.data.id)) {
      return reply.code(404).send({ error: 'thread_not_found' })
    }

    const thread = await prisma.messageThread.findFirst({
      where: {
        id: params.data.id,
        OR: [{ contextType: null }, { contextType: { not: 'market_listing' } }],
        participants: { some: { userId } },
      },
      select: {
        id: true,
        participants: { select: { userId: true, mutedUntil: true } },
      },
    })
    if (!thread) return reply.code(404).send({ error: 'thread_not_found' })

    const messageRecord = await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
      const normalizedBody = parse.data.body?.trim() ? sanitizePlainText(parse.data.body) : ''
      const created = await tx.message.create({
        data: {
          threadId: thread.id,
          senderId: userId,
          body: normalizedBody ? normalizedBody : null,
          attachments: parse.data.attachments ?? undefined,
          messageType: MessageType.text,
        },
        select: MESSAGE_SELECT,
      })

      await tx.messageThread.update({
        where: { id: thread.id },
        data: { lastMessageAt: created.createdAt },
      })

      await tx.messageParticipant.update({
        where: {
          threadId_userId: {
            threadId: thread.id,
            userId,
          },
        },
        data: { lastReadAt: created.createdAt, lastActivityAt: created.createdAt },
      })

      await tx.messageParticipant.updateMany({
        where: {
          threadId: thread.id,
          userId: { not: userId },
        },
        data: { lastActivityAt: created.createdAt },
      })

      return created
    })

    if (authContext.actor === 'family_member') {
      const counterpartId = thread.participants.find((participant: { userId: string }) => participant.userId !== userId)?.userId
      if (counterpartId) {
        await storeFamilyMessageThreadForMember({
          parentId: authContext.member.parentId,
          memberId: authContext.member.id,
          threadId: thread.id,
          peerUserId: counterpartId,
          timestamp: messageRecord.createdAt,
        })
      }
    }

    await Promise.all(
      thread.participants.map((participant: { userId: string }) =>
        dispatchRealtimeEvent(participant.userId, {
          type: 'message.created',
          data: {
            threadId: thread.id,
            message: formatMessage(messageRecord, participant.userId),
          },
        }),
      ),
    )

    void sendMobilePushForMessageCreated({
      threadId: thread.id,
      message: messageRecord,
      participants: thread.participants,
    })

    return reply.code(201).send({ message: formatMessage(messageRecord, userId) })
  }),
)

app.get('/messages/unread-count', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const authContext = await loadViewerAuthContext(req)
    if (!authContext) return reply.code(401).send({ error: 'unauthorized' })

    const userId = authContext.actor === 'family_member' ? authContext.member.parentId : authContext.userId
    const allowedThreadIds =
      authContext.actor === 'family_member'
        ? getFamilyMessageThreadIdsForMember(authContext.member.parent.communityMeta, authContext.member.id)
        : null

    const familyParentUnreadCount =
      authContext.actor === 'family_member'
        ? (getFamilyParentConversation(
            authContext.member.parent.communityMeta,
            authContext.member.id,
            authContext.member.parentId,
          )?.messages.filter((message) => {
            if (message.sender !== 'parent') return false
            const conversation = getFamilyParentConversation(
              authContext.member.parent.communityMeta,
              authContext.member.id,
              authContext.member.parentId,
            )
            if (!conversation?.childLastReadAt) return true
            return message.createdAt > conversation.childLastReadAt
          }).length ?? 0)
        : 0
    const parentFamilyUnreadCount =
      authContext.actor === 'user'
        ? getStoredFamilyParentConversations(
            (await prisma.user.findUnique({ where: { id: authContext.userId }, select: { communityMeta: true } }))?.communityMeta,
          ).reduce((total, conversation) => total + conversation.messages.filter((message) => {
            if (message.sender !== 'child') return false
            if (!conversation.parentLastReadAt) return true
            return message.createdAt > conversation.parentLastReadAt
          }).length, 0)
        : 0

    if (authContext.actor === 'family_member' && allowedThreadIds && allowedThreadIds.length === 0) {
      return reply.send({ count: familyParentUnreadCount })
    }

    let result: Array<{ count: number }>
    if (allowedThreadIds) {
      result = (await prisma.$queryRaw(Prisma.sql`
        SELECT COUNT(*)::int as count
        FROM "Message" m
        JOIN "MessageParticipant" mp ON m."threadId" = mp."threadId"
        JOIN "MessageThread" t ON t.id = m."threadId"
        WHERE mp."userId" = ${userId}
        AND m."senderId" != ${userId}
        AND (mp."lastReadAt" IS NULL OR m."createdAt" > mp."lastReadAt")
        AND (t."contextType" IS NULL OR t."contextType" != 'market_listing')
        AND m."threadId" IN (${Prisma.join(allowedThreadIds)})
      `)) as Array<{ count: number }>
    } else {
      result = await prisma.$queryRaw<Array<{ count: number }>>`
        SELECT COUNT(*)::int as count
        FROM "Message" m
        JOIN "MessageParticipant" mp ON m."threadId" = mp."threadId"
        JOIN "MessageThread" t ON t.id = m."threadId"
        WHERE mp."userId" = ${userId}
        AND m."senderId" != ${userId}
        AND (mp."lastReadAt" IS NULL OR m."createdAt" > mp."lastReadAt")
        AND (t."contextType" IS NULL OR t."contextType" != 'market_listing')
      `
    }
    const count = Number(result[0]?.count || 0) + familyParentUnreadCount + parentFamilyUnreadCount
    return reply.send({ count })
  }),
)

app.post('/messages/threads/:id/read', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const authContext = await loadViewerAuthContext(req)
    if (!authContext) return reply.code(401).send({ error: 'unauthorized' })

    const userId = authContext.actor === 'family_member' ? authContext.member.parentId : authContext.userId

    const params = MessageThreadIdParam.safeParse(req.params)
    if (!params.success) return reply.code(400).send({ error: params.error.flatten() })

    if (authContext.actor === 'user' && isParentFamilyThreadId(params.data.id)) {
      const memberId = parseParentFamilyThreadId(params.data.id)
      if (!memberId) return reply.code(404).send({ error: 'thread_not_found' })
      const parse = ThreadReadInput.safeParse(req.body ?? {})
      if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })
      const context = await loadParentFamilyConversationContext(authContext.userId, memberId)
      if (!context) return reply.code(404).send({ error: 'thread_not_found' })
      if (!context.conversation) {
        const readAt = new Date()
        return reply.send({ lastReadAt: readAt })
      }
      let readAt = new Date()
      if (parse.data.messageId) {
        const message = context.conversation.messages.find((entry) => entry.id === parse.data.messageId)
        if (!message) return reply.code(400).send({ error: 'invalid_message' })
        readAt = new Date(message.createdAt)
      }
      await markFamilyParentConversationRead({
        parentId: authContext.userId,
        memberId,
        actor: 'parent',
        readAt,
      })
      return reply.send({ lastReadAt: readAt })
    }

    if (authContext.actor === 'family_member' && params.data.id === buildFamilyParentThreadId(authContext.member.parentId)) {
      const parse = ThreadReadInput.safeParse(req.body ?? {})
      if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })
      const conversation =
        getFamilyParentConversation(
          authContext.member.parent.communityMeta,
          authContext.member.id,
          authContext.member.parentId,
        ) ?? null
      if (!conversation) {
        const readAt = new Date()
        return reply.send({ lastReadAt: readAt })
      }
      let readAt = new Date()
      if (parse.data.messageId) {
        const message = conversation.messages.find((entry) => entry.id === parse.data.messageId)
        if (!message) return reply.code(400).send({ error: 'invalid_message' })
        readAt = new Date(message.createdAt)
      }
      await markFamilyParentConversationRead({
        parentId: authContext.member.parentId,
        memberId: authContext.member.id,
        actor: 'child',
        readAt,
      })
      return reply.send({ lastReadAt: readAt })
    }

    if (authContext.actor === 'family_member' && !familyMemberCanAccessMessageThread(authContext.member, params.data.id)) {
      return reply.code(404).send({ error: 'thread_not_found' })
    }

    const membership = await prisma.messageParticipant.findUnique({
      where: {
        threadId_userId: {
          threadId: params.data.id,
          userId,
        },
        thread: {
          OR: [{ contextType: null }, { contextType: { not: 'market_listing' } }],
        },
      },
      select: { threadId: true },
    })
    if (!membership) return reply.code(404).send({ error: 'thread_not_found' })

    const parse = ThreadReadInput.safeParse(req.body ?? {})
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    let readAt = new Date()
    if (parse.data.messageId) {
      const message = await prisma.message.findUnique({
        where: { id: parse.data.messageId },
        select: { threadId: true, createdAt: true },
      })
      if (!message || message.threadId !== params.data.id) {
        return reply.code(400).send({ error: 'invalid_message' })
      }
      readAt = message.createdAt
    }

    await prisma.messageParticipant.update({
      where: {
        threadId_userId: {
          threadId: params.data.id,
          userId,
        },
      },
      data: { lastReadAt: readAt },
    })

    return reply.send({ lastReadAt: readAt })
  }),
)

