app.get('/admin/reports/summary', async (req: FastifyRequest, reply: FastifyReply) => {
  let user: { id: string; email: string | null } | null
  try {
    user = await loadAuthenticatedUser(req)
  } catch {
    return reply.code(401).send({ error: 'unauthorized' })
  }

  if (!user || !isSuperAdminEmail(user.email)) {
    return reply.code(403).send({ error: 'forbidden' })
  }

  const query = req.query as Record<string, string | undefined>
  const { start: startParam, end: endParam, format } = query
  const range = parseRange(startParam, endParam)
  const today = startOfUtcDay(new Date())

  const [
    totalUsers,
    usersToday,
    totalPosts,
    postsToday,
    totalComments,
    commentsToday,
    totalReactions,
    reactionsToday,
    totalCommunityFollows,
    totalBusinessFollows,
    communityFollowsToday,
    businessFollowsToday,
    userSeries,
    postSeries,
    commentSeries,
    reactionSeries,
    followSeries,
    pageViewSeries,
    jobsAddedSeries,
    applicantsSeries,
    applicationsViewedSeries,
    hiredSeries,
    routeTraffic,
    topPostViews,
    totalJobsAdded,
    jobsAddedToday,
    totalApplicants,
    applicantsToday,
    totalApplicationsViewed,
    applicationsViewedToday,
    totalApplicantsHired,
    applicantsHiredToday,
    organizationsViewedTotalRows,
    organizationsViewedTodayRows,
  ] = await Promise.all([
    prisma.user.count(),
    prisma.user.count({ where: { createdAt: { gte: today } } }),
    prisma.post.count(),
    prisma.post.count({ where: { createdAt: { gte: today } } }),
    prisma.comment.count(),
    prisma.comment.count({ where: { createdAt: { gte: today } } }),
    prisma.postReaction.count(),
    prisma.postReaction.count({ where: { createdAt: { gte: today } } }),
    prisma.communityFollow.count(),
    prisma.businessFollow.count(),
    prisma.communityFollow.count({ where: { createdAt: { gte: today } } }),
    prisma.businessFollow.count({ where: { createdAt: { gte: today } } }),
    queryDailyCounts('users', range),
    queryDailyCounts('posts', range),
    queryDailyCounts('comments', range),
    queryDailyCounts('reactions', range),
    queryFollowSeries(range),
    queryPageViewSeries(range),
    queryJobAnalyticsSeries('job_added', range),
    queryJobAnalyticsSeries('applicant_submitted', range),
    queryJobAnalyticsSeries('applications_viewed', range),
    queryJobAnalyticsSeries('applicant_hired', range),
    prisma.$queryRaw<Array<{ path: string; views: bigint }>>`
      select path, count(*)::bigint as views
      from "PageView"
      where "createdAt" >= ${range.start} and "createdAt" < ${range.end}
      group by path
      order by views desc
      limit 50
    `,
    prisma.$queryRaw<Array<{ postId: string; views: bigint; title: string | null }>>`
      select pv."postId" as "postId", count(*)::bigint as views, p.title as title
      from "PageView" pv
      join "Post" p on p.id = pv."postId"
      where pv."postId" is not null and pv."createdAt" >= ${range.start} and pv."createdAt" < ${range.end}
      group by pv."postId", p.title
      order by views desc
      limit 20
    `,
    prisma.$queryRaw<Array<{ count: bigint }>>`
      select count(*)::bigint as count
      from "JobAnalyticsEvent"
      where "kind" = 'job_added'::"JobAnalyticsEventKind"
    `,
    prisma.$queryRaw<Array<{ count: bigint }>>`
      select count(*)::bigint as count
      from "JobAnalyticsEvent"
      where "kind" = 'job_added'::"JobAnalyticsEventKind"
        and "createdAt" >= ${today}
    `,
    prisma.$queryRaw<Array<{ count: bigint }>>`
      select count(*)::bigint as count
      from "JobAnalyticsEvent"
      where "kind" = 'applicant_submitted'::"JobAnalyticsEventKind"
    `,
    prisma.$queryRaw<Array<{ count: bigint }>>`
      select count(*)::bigint as count
      from "JobAnalyticsEvent"
      where "kind" = 'applicant_submitted'::"JobAnalyticsEventKind"
        and "createdAt" >= ${today}
    `,
    prisma.$queryRaw<Array<{ count: bigint }>>`
      select count(*)::bigint as count
      from "JobAnalyticsEvent"
      where "kind" = 'applications_viewed'::"JobAnalyticsEventKind"
    `,
    prisma.$queryRaw<Array<{ count: bigint }>>`
      select count(*)::bigint as count
      from "JobAnalyticsEvent"
      where "kind" = 'applications_viewed'::"JobAnalyticsEventKind"
        and "createdAt" >= ${today}
    `,
    prisma.$queryRaw<Array<{ count: bigint }>>`
      select count(*)::bigint as count
      from "JobAnalyticsEvent"
      where "kind" = 'applicant_hired'::"JobAnalyticsEventKind"
    `,
    prisma.$queryRaw<Array<{ count: bigint }>>`
      select count(*)::bigint as count
      from "JobAnalyticsEvent"
      where "kind" = 'applicant_hired'::"JobAnalyticsEventKind"
        and "createdAt" >= ${today}
    `,
    prisma.$queryRaw<Array<{ count: bigint }>>`
      select count(distinct "businessId")::bigint as count
      from "JobAnalyticsEvent"
      where "kind" = 'applications_viewed'::"JobAnalyticsEventKind"
    `,
    prisma.$queryRaw<Array<{ count: bigint }>>`
      select count(distinct "businessId")::bigint as count
      from "JobAnalyticsEvent"
      where "kind" = 'applications_viewed'::"JobAnalyticsEventKind"
        and "createdAt" >= ${today}
    `,
  ])

  const jobsAddedTotalCount = Number(totalJobsAdded[0]?.count ?? 0)
  const jobsAddedTodayCount = Number(jobsAddedToday[0]?.count ?? 0)
  const followsTotalCount = totalCommunityFollows + totalBusinessFollows
  const followsTodayCount = communityFollowsToday + businessFollowsToday
  const applicantsTotalCount = Number(totalApplicants[0]?.count ?? 0)
  const applicantsTodayCount = Number(applicantsToday[0]?.count ?? 0)
  const applicationsViewedTotalCount = Number(totalApplicationsViewed[0]?.count ?? 0)
  const applicationsViewedTodayCount = Number(applicationsViewedToday[0]?.count ?? 0)
  const applicantsHiredTotalCount = Number(totalApplicantsHired[0]?.count ?? 0)
  const applicantsHiredTodayCount = Number(applicantsHiredToday[0]?.count ?? 0)
  const organizationsViewedTotalCount = Number(organizationsViewedTotalRows[0]?.count ?? 0)
  const organizationsViewedTodayCount = Number(organizationsViewedTodayRows[0]?.count ?? 0)

  const responsePayload = {
    generatedAt: new Date().toISOString(),
    users: {
      total: totalUsers,
      today: usersToday,
      series: userSeries,
    },
    posts: {
      total: totalPosts,
      today: postsToday,
      series: postSeries,
    },
    comments: {
      total: totalComments,
      today: commentsToday,
      series: commentSeries,
    },
    reactions: {
      total: totalReactions,
      today: reactionsToday,
      series: reactionSeries,
    },
    follows: {
      total: followsTotalCount,
      today: followsTodayCount,
      series: followSeries,
    },
    jobs: {
      added: {
        total: jobsAddedTotalCount,
        today: jobsAddedTodayCount,
        series: jobsAddedSeries,
      },
      applicants: {
        total: applicantsTotalCount,
        today: applicantsTodayCount,
        series: applicantsSeries,
      },
      applicationsViewed: {
        views: {
          total: applicationsViewedTotalCount,
          today: applicationsViewedTodayCount,
          series: applicationsViewedSeries,
        },
        organizations: {
          total: organizationsViewedTotalCount,
          today: organizationsViewedTodayCount,
        },
      },
      hired: {
        total: applicantsHiredTotalCount,
        today: applicantsHiredTodayCount,
        series: hiredSeries,
      },
    },
    pageViews: {
      series: pageViewSeries,
    },
    traffic: {
      routes: routeTraffic.map((row: { path: string; views: bigint }) => ({ path: row.path, views: Number(row.views) || 0 })),
      posts: topPostViews.map((row: { postId: string; views: bigint; title: string | null }) => ({ postId: row.postId, views: Number(row.views) || 0, title: row.title })),
    },
  }

  if (format === 'csv') {
    const dateMap = new Map<string, {
      users?: number
      posts?: number
      comments?: number
      reactions?: number
      views?: number
      jobsAdded?: number
      applicants?: number
      applicationsViewed?: number
      hired?: number
    }>()
    const ingest = (series: DailyCount[], key: keyof NonNullable<ReturnType<typeof dateMap.get>>) => {
      series.forEach((point) => {
        const existing = dateMap.get(point.date) || {}
        existing[key] = point.count
        dateMap.set(point.date, existing)
      })
    }
    ingest(userSeries, 'users')
    ingest(postSeries, 'posts')
    ingest(commentSeries, 'comments')
    ingest(reactionSeries, 'reactions')
    ingest(pageViewSeries, 'views')
    ingest(jobsAddedSeries, 'jobsAdded')
    ingest(applicantsSeries, 'applicants')
    ingest(applicationsViewedSeries, 'applicationsViewed')
    ingest(hiredSeries, 'hired')

    const sortedDates = Array.from(dateMap.keys()).sort((a, b) => new Date(a).getTime() - new Date(b).getTime())
    const rows = sortedDates.map((date) => {
      const entry = dateMap.get(date) || {}
      return [
        date,
        entry.users ?? 0,
        entry.posts ?? 0,
        entry.comments ?? 0,
        entry.reactions ?? 0,
        entry.views ?? 0,
        entry.jobsAdded ?? 0,
        entry.applicants ?? 0,
        entry.applicationsViewed ?? 0,
        entry.hired ?? 0,
      ].join(',')
    })

    const csv = ['date,users,posts,comments,reactions,pageViews,jobsAdded,applicants,applicationsViewed,applicantsHired', ...rows].join('\n')
    return reply.header('content-type', 'text/csv').send(csv)
  }

  return reply.send(responsePayload)
})

app.get('/admin/reports/detail', async (req: FastifyRequest, reply: FastifyReply) => {
  const user = await loadAdminUserOrReply(req, reply)
  if (!user) return

  const query = AdminAnalyticsDetailQuery.safeParse(req.query ?? {})
  if (!query.success) return reply.code(400).send({ error: query.error.flatten() })

  const range = parseRange(query.data.start, query.data.end)
  const limit = query.data.limit
  const normalizedSearch = query.data.search ? normalizeSearchTerm(query.data.search) : ''

  if (query.data.metric === 'users') {
    const users = await prisma.user.findMany({
      where: normalizedSearch
        ? buildAdminUserSearchWhere(normalizedSearch)
        : { createdAt: { gte: range.start, lt: range.end } },
      orderBy: [{ createdAt: 'desc' }],
      take: limit,
      select: {
        id: true,
        email: true,
        handle: true,
        name: true,
        avatarUrl: true,
        coverUrl: true,
        createdAt: true,
        lastLoginAt: true,
        premiumStatus: true,
        communityFollows: {
          orderBy: [{ home: 'desc' }, { createdAt: 'asc' }],
          take: 3,
          select: {
            provinceCode: true,
            communitySlug: true,
            home: true,
          },
        },
        _count: {
          select: {
            posts: true,
            comments: true,
            businesses: true,
            contentReportsFiled: true,
            contentReportsTargeting: true,
            communityFollows: true,
          },
        },
      },
    })

    return reply.send({
      metric: query.data.metric,
      generatedAt: new Date().toISOString(),
      items: users.map((entry: any) => ({
        ...formatAdminUserSummary(entry),
        email: entry.email,
        createdAt: entry.createdAt.toISOString(),
        lastLoginAt: entry.lastLoginAt?.toISOString() ?? null,
        premiumStatus: entry.premiumStatus,
        communities: {
          count: entry._count.communityFollows,
          items: entry.communityFollows.map((community: any) => ({
            provinceCode: community.provinceCode,
            communitySlug: community.communitySlug,
            home: community.home,
            label: formatCommunityFollowLabel(community),
            href: buildCommunityHref(community.provinceCode, community.communitySlug),
          })),
        },
        postCount: entry._count.posts,
        commentCount: entry._count.comments,
        organizationsOwned: entry._count.businesses,
        reportsFiled: entry._count.contentReportsFiled,
        reportsAgainst: entry._count.contentReportsTargeting,
      })),
    })
  }

  if (query.data.metric === 'posts') {
    await ensureContentAiScanTables()
    await ensureCitizenMarketplaceTables()

    const page = query.data.page
    const pageSize = query.data.limit
    const offset = (page - 1) * pageSize
    const sourceTake = Math.min(offset + pageSize + 1, 600)

    let flaggedPostIds: string[] | null = null
    let flaggedListingIds: string[] | null = null

    if (query.data.flagReason) {
      const flaggedReports = await prisma.contentReport.findMany({
        where: {
          targetType: { in: [ModerationTargetType.POST, ModerationTargetType.MARKET_LISTING] },
          reasons: { has: query.data.flagReason },
        },
        select: { targetId: true, targetType: true },
        take: 500,
      })
      flaggedPostIds = Array.from(
        new Set(flaggedReports.filter((entry: any) => entry.targetType === ModerationTargetType.POST).map((entry: any) => entry.targetId)),
      )
      flaggedListingIds = Array.from(
        new Set(flaggedReports.filter((entry: any) => entry.targetType === ModerationTargetType.MARKET_LISTING).map((entry: any) => entry.targetId)),
      )
      if (!flaggedPostIds.length && !flaggedListingIds.length) {
        return reply.send({ metric: query.data.metric, generatedAt: new Date().toISOString(), items: [], page, hasMore: false })
      }
    }

    const posts = await prisma.post.findMany({
      where: {
        ...(query.data.authorId ? { authorId: query.data.authorId } : {}),
        ...(!query.data.authorId ? { createdAt: { gte: range.start, lt: range.end } } : {}),
        ...(flaggedPostIds ? { id: { in: flaggedPostIds } } : {}),
        ...(normalizedSearch
          ? {
              OR: [
                { title: { contains: normalizedSearch, mode: 'insensitive' } },
                { body: { contains: normalizedSearch, mode: 'insensitive' } },
                { author: { handle: { contains: normalizedSearch.replace(/^@/, ''), mode: 'insensitive' } } },
                { author: { name: { contains: normalizedSearch, mode: 'insensitive' } } },
              ],
            }
          : {}),
      },
      orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
      take: sourceTake,
      select: {
        id: true,
        title: true,
        body: true,
        createdAt: true,
        seoSlug: true,
        provinceCode: true,
        communitySlug: true,
        jurisdiction: true,
        moderationStatus: true,
        commentCount: true,
        upvotes: true,
        downvotes: true,
        reactionTotal: true,
        author: {
          select: {
            id: true,
            handle: true,
            name: true,
            avatarUrl: true,
            coverUrl: true,
          },
        },
        business: {
          select: {
            id: true,
            name: true,
            slug: true,
            provinceCode: true,
            communitySlug: true,
          },
        },
      },
    })

    const listingSearchLike = `%${normalizedSearch}%`
    const listingHandleLike = `%${normalizedSearch.replace(/^@/, '')}%`
    const listingWhereClauses: Prisma.Sql[] = [
      Prisma.sql`l.is_active = TRUE`,
    ]

    if (query.data.authorId) {
      listingWhereClauses.push(Prisma.sql`l.seller_user_id = ${query.data.authorId}`)
    } else {
      listingWhereClauses.push(Prisma.sql`l.created_at >= ${range.start}`)
      listingWhereClauses.push(Prisma.sql`l.created_at < ${range.end}`)
    }

    if (flaggedListingIds) {
      listingWhereClauses.push(Prisma.sql`l.id IN (${Prisma.join(flaggedListingIds)})`)
    }

    if (normalizedSearch) {
      listingWhereClauses.push(Prisma.sql`
        (
          LOWER(COALESCE(l.title, '')) LIKE ${listingSearchLike}
          OR LOWER(COALESCE(l.description, '')) LIKE ${listingSearchLike}
          OR LOWER(COALESCE(u.handle, '')) LIKE ${listingHandleLike}
          OR LOWER(COALESCE(u.name, '')) LIKE ${listingSearchLike}
        )
      `)
    }

    const listings = (await prisma.$queryRaw(Prisma.sql`
      SELECT
        l.id,
        l.seller_user_id,
        l.title,
        l.description,
        l.price_cents,
        l.currency,
        l.pickup_city,
        l.pickup_province,
        l.listing_province_code,
        l.listing_community_slug,
        l.moderation_status,
        l.status,
        l.created_at,
        u.handle AS seller_handle,
        u.name AS seller_name,
        u."avatarUrl" AS seller_avatar_url,
        u."coverUrl" AS seller_cover_url
      FROM citizen_market_listing l
      INNER JOIN "User" u ON u.id = l.seller_user_id
      WHERE ${Prisma.join(listingWhereClauses, ' AND ')}
      ORDER BY l.created_at DESC, l.id DESC
      LIMIT ${sourceTake}
    `)) as Array<{
      id: string
      seller_user_id: string
      title: string
      description: string | null
      price_cents: number
      currency: string
      pickup_city: string | null
      pickup_province: string | null
      listing_province_code: string | null
      listing_community_slug: string | null
      moderation_status: string
      status: string
      created_at: Date
      seller_handle: string
      seller_name: string | null
      seller_avatar_url: string | null
      seller_cover_url: string | null
    }>

    const eventBusinesses = await prisma.business.findMany({
      where: query.data.authorId ? { ownerId: query.data.authorId } : undefined,
      select: {
        id: true,
        ownerId: true,
        name: true,
        slug: true,
        provinceCode: true,
        communitySlug: true,
        metadata: true,
        owner: {
          select: {
            id: true,
            handle: true,
            name: true,
            avatarUrl: true,
            coverUrl: true,
          },
        },
      },
    })

    const eventRows: Array<{ business: (typeof eventBusinesses)[number]; event: OrgEventDefinition }> = eventBusinesses
      .flatMap((business: (typeof eventBusinesses)[number]) => {
        const system = readOrganizationSystemState(business.metadata)
        return system.events.map((event) => ({ business, event }))
      })
      .filter(({ event }: { event: OrgEventDefinition }) => {
        const createdAt = new Date(event.createdAt)
        if (Number.isNaN(createdAt.getTime())) return false
        if (!query.data.authorId && (createdAt < range.start || createdAt >= range.end)) return false
        if (!normalizedSearch) return true
        const haystack = buildSearchableText(event.title, stripHtmlToPlainText(event.description ?? ''))
        return haystack.includes(normalizedSearch)
      })
      .sort((left: { business: (typeof eventBusinesses)[number]; event: OrgEventDefinition }, right: { business: (typeof eventBusinesses)[number]; event: OrgEventDefinition }) => {
        const leftTime = new Date(left.event.createdAt).getTime()
        const rightTime = new Date(right.event.createdAt).getTime()
        if (rightTime !== leftTime) return rightTime - leftTime
        return left.event.id.localeCompare(right.event.id)
      })
      .slice(0, sourceTake)

    const postIds = posts.map((entry: any) => entry.id)
    const listingIds = listings.map((entry: (typeof listings)[number]) => entry.id)

    const reportRows = postIds.length || listingIds.length
      ? await prisma.contentReport.findMany({
          where: {
            OR: [
              ...(postIds.length ? [{ targetType: ModerationTargetType.POST, targetId: { in: postIds } }] : []),
              ...(listingIds.length ? [{ targetType: ModerationTargetType.MARKET_LISTING, targetId: { in: listingIds } }] : []),
            ],
          },
          orderBy: [{ createdAt: 'desc' }],
          select: {
            targetType: true,
            targetId: true,
            reasons: true,
            status: true,
            createdAt: true,
          },
        })
      : []

    const reportsByTargetKey = new Map<string, Array<{ reasons: string[]; status: ContentReportStatus; createdAt: Date }>>()
    reportRows.forEach((report: any) => {
      const bucket = reportsByTargetKey.get(`${report.targetType}:${report.targetId}`) ?? []
      bucket.push(report)
      reportsByTargetKey.set(`${report.targetType}:${report.targetId}`, bucket)
    })

    const postScanRows = postIds.length
      ? await prisma.$queryRaw<Array<{
          target_id: string
          status: string
          moderation_state: string | null
          label_summary: string | null
          labels: unknown
          moderation_flags: unknown
          error_text: string | null
          updated_at: Date | null
          completed_at: Date | null
        }>>`
          SELECT target_id, status, moderation_state, label_summary, labels, moderation_flags, error_text, updated_at, completed_at
          FROM content_ai_scan
          WHERE target_type = ${'post'}
            AND target_id IN (${Prisma.join(postIds)})
        `
      : []

    const listingScanRows = listingIds.length
      ? await prisma.$queryRaw<Array<{
          target_id: string
          status: string
          moderation_state: string | null
          label_summary: string | null
          labels: unknown
          moderation_flags: unknown
          error_text: string | null
          updated_at: Date | null
          completed_at: Date | null
        }>>`
          SELECT target_id, status, moderation_state, label_summary, labels, moderation_flags, error_text, updated_at, completed_at
          FROM content_ai_scan
          WHERE target_type = ${'market_listing'}
            AND target_id IN (${Prisma.join(listingIds)})
        `
      : []

    const eventScanTargetIds = eventRows.map(({ business, event }: { business: (typeof eventBusinesses)[number]; event: OrgEventDefinition }) => buildOrganizationEventScanTargetId(business.id, event.id))
    const eventScanRows = eventScanTargetIds.length
      ? await prisma.$queryRaw<Array<{
          target_id: string
          status: string
          moderation_state: string | null
          label_summary: string | null
          labels: unknown
          moderation_flags: unknown
          error_text: string | null
          updated_at: Date | null
          completed_at: Date | null
        }>>`
          SELECT target_id, status, moderation_state, label_summary, labels, moderation_flags, error_text, updated_at, completed_at
          FROM content_ai_scan
          WHERE target_type = ${'organization_event'}
            AND target_id IN (${Prisma.join(eventScanTargetIds)})
        `
      : []

    const scansByTargetKey = new Map<string, ContentAiScanSummary>()
    const ingestScanRows = (targetType: ContentAiScanTargetType, rows: Array<{
      target_id: string
      status: string
      moderation_state: string | null
      label_summary: string | null
      labels: unknown
      moderation_flags: unknown
      error_text: string | null
      updated_at: Date | null
      completed_at: Date | null
    }>) => {
      rows.forEach((scan) => {
        scansByTargetKey.set(`${targetType}:${scan.target_id}`, {
          status: scan.status,
          moderationState: scan.moderation_state,
          labelSummary: scan.label_summary,
          labels: readStringList(scan.labels),
          moderationFlags: readStringList(scan.moderation_flags),
          errorText: scan.error_text,
          updatedAt: scan.updated_at?.toISOString() ?? null,
          completedAt: scan.completed_at?.toISOString() ?? null,
        })
      })
    }

    ingestScanRows('post', postScanRows)
    ingestScanRows('market_listing', listingScanRows)
    ingestScanRows('organization_event', eventScanRows)

    const items = [
      ...posts.map((post: any) => {
        const reportSummary = summarizeReportReasons(reportsByTargetKey.get(`${ModerationTargetType.POST}:${post.id}`) ?? [])
        return {
          id: `post:${post.id}`,
          aiScanTargetType: 'post',
          aiScanTargetId: post.id,
          createdAt: post.createdAt.toISOString(),
          contentType: 'social_post',
          title: post.title?.trim() || null,
          preview: sanitizePlainText(post.body).slice(0, 220).trim(),
          url: buildPostHrefForAdmin(post),
          sourceLabel: post.business ? 'Organization post' : post.communitySlug ? 'Community post' : 'Citizen post',
          metaLine: post.jurisdiction,
          moderationStatus: post.moderationStatus,
          commentCount: post.commentCount,
          reactionCount: post.reactionTotal,
          score: post.upvotes - post.downvotes,
          author: formatAdminUserSummary(post.author),
          organization: post.business
            ? {
                id: post.business.id,
                name: post.business.name,
                slug: post.business.slug,
                href: buildBusinessHrefForAdmin(post.business),
              }
            : null,
          flags: reportSummary,
          aiScan: scansByTargetKey.get(`post:${post.id}`) ?? buildContentAiScanDefaultSummary(),
        }
      }),
      ...listings.map((listing: (typeof listings)[number]) => {
        const reportSummary = summarizeReportReasons(reportsByTargetKey.get(`${ModerationTargetType.MARKET_LISTING}:${listing.id}`) ?? [])
        const locationLabel = [listing.pickup_city, listing.pickup_province].filter(Boolean).join(', ')
        let priceLabel = `${((Number(listing.price_cents) || 0) / 100).toFixed(2)} ${listing.currency}`
        try {
          priceLabel = new Intl.NumberFormat('en-CA', { style: 'currency', currency: String(listing.currency || 'CAD').toUpperCase() }).format((Number(listing.price_cents) || 0) / 100)
        } catch {
          priceLabel = `${((Number(listing.price_cents) || 0) / 100).toFixed(2)} ${listing.currency}`
        }
        return {
          id: `market_listing:${listing.id}`,
          aiScanTargetType: 'market_listing',
          aiScanTargetId: listing.id,
          createdAt: listing.created_at.toISOString(),
          contentType: 'market_listing',
          title: listing.title?.trim() || null,
          preview: sanitizePlainText(listing.description ?? '').slice(0, 220).trim(),
          url: `/market/listings/${encodeURIComponent(listing.id)}`,
          sourceLabel: 'Market listing',
          metaLine: [priceLabel, locationLabel].filter(Boolean).join(' · ') || null,
          moderationStatus: listing.moderation_status,
          commentCount: 0,
          reactionCount: 0,
          score: 0,
          author: formatAdminUserSummary({
            id: listing.seller_user_id,
            handle: listing.seller_handle,
            name: listing.seller_name,
            avatarUrl: listing.seller_avatar_url,
            coverUrl: listing.seller_cover_url,
          }),
          organization: null,
          flags: reportSummary,
          aiScan: scansByTargetKey.get(`market_listing:${listing.id}`) ?? buildContentAiScanDefaultSummary(),
        }
      }),
      ...eventRows.map(({ business, event }: { business: (typeof eventBusinesses)[number]; event: OrgEventDefinition }) => ({
        id: `organization_event:${event.id}`,
        aiScanTargetType: 'organization_event',
        aiScanTargetId: buildOrganizationEventScanTargetId(business.id, event.id),
        createdAt: new Date(event.createdAt).toISOString(),
        contentType: 'organization_event',
        title: event.title?.trim() || null,
        preview: sanitizePlainText(event.description ?? '').slice(0, 220).trim(),
        url:
          business.provinceCode && business.communitySlug && business.slug
            ? `/com/${encodeURIComponent(business.provinceCode.toLowerCase())}/${encodeURIComponent(business.communitySlug.toLowerCase())}/orgs/${encodeURIComponent(business.slug)}/events/${encodeURIComponent(event.id)}`
            : null,
        sourceLabel: 'Organization event',
        metaLine: event.startsAt ? `Starts ${new Date(event.startsAt).toLocaleString()}` : null,
        moderationStatus: event.status ?? 'PUBLISHED',
        commentCount: 0,
        reactionCount: 0,
        score: 0,
        author: formatAdminUserSummary(business.owner),
        organization: {
          id: business.id,
          name: business.name,
          slug: business.slug,
          href: buildBusinessHrefForAdmin(business),
        },
        flags: summarizeReportReasons([]),
        aiScan:
          scansByTargetKey.get(`organization_event:${buildOrganizationEventScanTargetId(business.id, event.id)}`) ??
          buildContentAiScanDefaultSummary(),
      })),
    ]
      .sort((left, right) => {
        const leftTime = new Date(left.createdAt).getTime()
        const rightTime = new Date(right.createdAt).getTime()
        if (rightTime !== leftTime) return rightTime - leftTime
        return left.id.localeCompare(right.id)
      })

    const pagedItems = items.slice(offset, offset + pageSize)
    const hasMore = offset + pageSize < items.length

    return reply.send({
      metric: query.data.metric,
      generatedAt: new Date().toISOString(),
      items: pagedItems,
      page,
      hasMore,
    })
  }

  if (query.data.metric === 'comments') {
    const comments = await prisma.comment.findMany({
      where: { createdAt: { gte: range.start, lt: range.end } },
      orderBy: [{ createdAt: 'desc' }],
      take: limit,
      select: {
        id: true,
        body: true,
        createdAt: true,
        moderationStatus: true,
        upvotes: true,
        downvotes: true,
        user: {
          select: {
            id: true,
            handle: true,
            name: true,
            avatarUrl: true,
            coverUrl: true,
          },
        },
        post: {
          select: {
            id: true,
            title: true,
            body: true,
            seoSlug: true,
            provinceCode: true,
            communitySlug: true,
            business: {
              select: {
                provinceCode: true,
                communitySlug: true,
              },
            },
            author: {
              select: {
                handle: true,
              },
            },
          },
        },
      },
    })

    const scanRows = comments.length
      ? await prisma.$queryRaw<Array<{
          target_id: string
          status: string
          moderation_state: string | null
          label_summary: string | null
          labels: unknown
          moderation_flags: unknown
          error_text: string | null
          updated_at: Date | null
          completed_at: Date | null
        }>>`
          SELECT target_id, status, moderation_state, label_summary, labels, moderation_flags, error_text, updated_at, completed_at
          FROM content_ai_scan
          WHERE target_type = ${'comment'}
            AND target_id IN (${Prisma.join(comments.map((entry: any) => entry.id))})
        `
      : []

    const scansByCommentId = new Map<string, ContentAiScanSummary>()
    scanRows.forEach((scan: {
      target_id: string
      status: string
      moderation_state: string | null
      label_summary: string | null
      labels: unknown
      moderation_flags: unknown
      error_text: string | null
      updated_at: Date | null
      completed_at: Date | null
    }) => {
      scansByCommentId.set(scan.target_id, {
        status: scan.status,
        moderationState: scan.moderation_state,
        labelSummary: scan.label_summary,
        labels: readStringList(scan.labels),
        moderationFlags: readStringList(scan.moderation_flags),
        errorText: scan.error_text,
        updatedAt: scan.updated_at?.toISOString() ?? null,
        completedAt: scan.completed_at?.toISOString() ?? null,
      })
    })

    return reply.send({
      metric: query.data.metric,
      generatedAt: new Date().toISOString(),
      items: comments.map((entry: any) => ({
        id: entry.id,
        aiScanTargetType: 'comment',
        aiScanTargetId: entry.id,
        createdAt: entry.createdAt.toISOString(),
        body: sanitizePlainText(entry.body).slice(0, 220).trim(),
        moderationStatus: entry.moderationStatus,
        score: entry.upvotes - entry.downvotes,
        author: formatAdminUserSummary(entry.user),
        post: {
          id: entry.post.id,
          title: entry.post.title?.trim() || sanitizePlainText(entry.post.body).slice(0, 90) || 'Untitled post',
          url: buildPostHrefForAdmin(entry.post),
        },
        aiScan: scansByCommentId.get(entry.id) ?? buildContentAiScanDefaultSummary(),
      })),
    })
  }

  if (query.data.metric === 'reactions') {
    const reactions = await prisma.postReaction.findMany({
      where: { createdAt: { gte: range.start, lt: range.end } },
      orderBy: [{ createdAt: 'desc' }],
      take: limit,
      select: {
        createdAt: true,
        type: true,
        user: {
          select: {
            id: true,
            handle: true,
            name: true,
            avatarUrl: true,
            coverUrl: true,
          },
        },
        post: {
          select: {
            id: true,
            title: true,
            body: true,
            seoSlug: true,
            provinceCode: true,
            communitySlug: true,
            business: {
              select: {
                provinceCode: true,
                communitySlug: true,
              },
            },
            author: {
              select: {
                handle: true,
              },
            },
          },
        },
      },
    })

    return reply.send({
      metric: query.data.metric,
      generatedAt: new Date().toISOString(),
      items: reactions.map((entry: any) => ({
        createdAt: entry.createdAt.toISOString(),
        type: entry.type,
        user: formatAdminUserSummary(entry.user),
        post: {
          id: entry.post.id,
          title: entry.post.title?.trim() || sanitizePlainText(entry.post.body).slice(0, 90) || 'Untitled post',
          url: buildPostHrefForAdmin(entry.post),
        },
      })),
    })
  }

  if (query.data.metric === 'follows') {
    const [communityFollows, businessFollows] = await Promise.all([
      prisma.communityFollow.findMany({
        where: { createdAt: { gte: range.start, lt: range.end } },
        orderBy: [{ createdAt: 'desc' }],
        take: limit,
        select: {
          id: true,
          createdAt: true,
          provinceCode: true,
          communitySlug: true,
          user: {
            select: {
              id: true,
              handle: true,
              name: true,
              avatarUrl: true,
              coverUrl: true,
            },
          },
        },
      }),
      prisma.businessFollow.findMany({
        where: { createdAt: { gte: range.start, lt: range.end } },
        orderBy: [{ createdAt: 'desc' }],
        take: limit,
        select: {
          id: true,
          createdAt: true,
          user: {
            select: {
              id: true,
              handle: true,
              name: true,
              avatarUrl: true,
              coverUrl: true,
            },
          },
          business: {
            select: {
              id: true,
              name: true,
              slug: true,
              provinceCode: true,
              communitySlug: true,
            },
          },
        },
      }),
    ])

    const items = [
      ...communityFollows.map((entry: any) => ({
        id: entry.id,
        createdAt: entry.createdAt.toISOString(),
        type: 'community',
        user: formatAdminUserSummary(entry.user),
        label: `${entry.provinceCode.toUpperCase()} / ${entry.communitySlug}`,
        href: buildCommunityHref(entry.provinceCode, entry.communitySlug),
      })),
      ...businessFollows.map((entry: any) => ({
        id: entry.id,
        createdAt: entry.createdAt.toISOString(),
        type: 'organization',
        user: formatAdminUserSummary(entry.user),
        label: entry.business.name,
        href: buildBusinessHrefForAdmin(entry.business),
      })),
    ]
      .sort((left, right) => new Date(right.createdAt).getTime() - new Date(left.createdAt).getTime())
      .slice(0, limit)

    return reply.send({ metric: query.data.metric, generatedAt: new Date().toISOString(), items })
  }

  if (query.data.metric === 'jobsAdded') {
    const jobs = await prisma.jobPosting.findMany({
      where: { createdAt: { gte: range.start, lt: range.end } },
      orderBy: [{ createdAt: 'desc' }],
      take: limit,
      select: {
        id: true,
        title: true,
        createdAt: true,
        status: true,
        applicantCount: true,
        publishedAt: true,
        business: {
          select: {
            id: true,
            name: true,
            slug: true,
            provinceCode: true,
            communitySlug: true,
          },
        },
        createdBy: {
          select: {
            id: true,
            handle: true,
            name: true,
            avatarUrl: true,
            coverUrl: true,
          },
        },
      },
    })

    return reply.send({
      metric: query.data.metric,
      generatedAt: new Date().toISOString(),
      items: jobs.map((entry: any) => ({
        id: entry.id,
        createdAt: entry.createdAt.toISOString(),
        title: entry.title,
        status: entry.status,
        publishedAt: entry.publishedAt?.toISOString() ?? null,
        applicantCount: entry.applicantCount,
        organization: {
          id: entry.business.id,
          name: entry.business.name,
          href: buildBusinessHrefForAdmin(entry.business),
        },
        createdBy: formatAdminUserSummary(entry.createdBy),
      })),
    })
  }

  if (query.data.metric === 'applicants') {
    const applicants = await prisma.jobApplication.findMany({
      where: { createdAt: { gte: range.start, lt: range.end } },
      orderBy: [{ createdAt: 'desc' }],
      take: limit,
      select: {
        id: true,
        createdAt: true,
        status: true,
        applicant: {
          select: {
            id: true,
            handle: true,
            name: true,
            avatarUrl: true,
            coverUrl: true,
          },
        },
        jobPosting: {
          select: {
            id: true,
            title: true,
            status: true,
            business: {
              select: {
                id: true,
                name: true,
                slug: true,
                provinceCode: true,
                communitySlug: true,
              },
            },
          },
        },
      },
    })

    return reply.send({
      metric: query.data.metric,
      generatedAt: new Date().toISOString(),
      items: applicants.map((entry: any) => ({
        id: entry.id,
        createdAt: entry.createdAt.toISOString(),
        status: entry.status,
        applicant: formatAdminUserSummary(entry.applicant),
        job: {
          id: entry.jobPosting.id,
          title: entry.jobPosting.title,
          status: entry.jobPosting.status,
        },
        organization: {
          id: entry.jobPosting.business.id,
          name: entry.jobPosting.business.name,
          href: buildBusinessHrefForAdmin(entry.jobPosting.business),
        },
      })),
    })
  }

  if (query.data.metric === 'applicationsViewed') {
    const views = await prisma.jobAnalyticsEvent.findMany({
      where: {
        kind: 'applications_viewed',
        createdAt: { gte: range.start, lt: range.end },
      },
      orderBy: [{ createdAt: 'desc' }],
      take: limit,
      select: {
        id: true,
        createdAt: true,
        actor: {
          select: {
            id: true,
            handle: true,
            name: true,
            avatarUrl: true,
            coverUrl: true,
          },
        },
        jobPosting: {
          select: {
            id: true,
            title: true,
          },
        },
        business: {
          select: {
            id: true,
            name: true,
            slug: true,
            provinceCode: true,
            communitySlug: true,
          },
        },
      },
    })

    return reply.send({
      metric: query.data.metric,
      generatedAt: new Date().toISOString(),
      items: views.map((entry: any) => ({
        id: entry.id,
        createdAt: entry.createdAt.toISOString(),
        viewer: entry.actor ? formatAdminUserSummary(entry.actor) : null,
        job: entry.jobPosting ? { id: entry.jobPosting.id, title: entry.jobPosting.title } : null,
        organization: {
          id: entry.business.id,
          name: entry.business.name,
          href: buildBusinessHrefForAdmin(entry.business),
        },
      })),
    })
  }

  if (query.data.metric === 'hired') {
    const hires = await prisma.jobAnalyticsEvent.findMany({
      where: {
        kind: 'applicant_hired',
        createdAt: { gte: range.start, lt: range.end },
      },
      orderBy: [{ createdAt: 'desc' }],
      take: limit,
      select: {
        id: true,
        createdAt: true,
        jobPosting: {
          select: {
            id: true,
            title: true,
          },
        },
        jobApplication: {
          select: {
            applicant: {
              select: {
                id: true,
                handle: true,
                name: true,
                avatarUrl: true,
                coverUrl: true,
              },
            },
          },
        },
        business: {
          select: {
            id: true,
            name: true,
            slug: true,
            provinceCode: true,
            communitySlug: true,
          },
        },
      },
    })

    return reply.send({
      metric: query.data.metric,
      generatedAt: new Date().toISOString(),
      items: hires.map((entry: any) => ({
        id: entry.id,
        createdAt: entry.createdAt.toISOString(),
        applicant: entry.jobApplication?.applicant ? formatAdminUserSummary(entry.jobApplication.applicant) : null,
        job: entry.jobPosting ? { id: entry.jobPosting.id, title: entry.jobPosting.title } : null,
        organization: {
          id: entry.business.id,
          name: entry.business.name,
          href: buildBusinessHrefForAdmin(entry.business),
        },
      })),
    })
  }

  return reply.code(400).send({ error: 'unsupported_metric' })
})

app.post('/admin/content-ai-scans/retry', async (req: FastifyRequest, reply: FastifyReply) => {
  const adminUser = await loadAdminUserOrReply(req, reply)
  if (!adminUser) return

  const body = AdminContentAiScanRetryBody.safeParse(req.body ?? {})
  if (!body.success) return reply.code(400).send({ error: body.error.flatten() })

  const retried = await retryContentAiScanTarget(body.data)
  if (!retried) return reply.code(404).send({ error: 'content_ai_scan_target_not_found' })

  return reply.send({ queued: true })
})

app.get('/admin/users/:userId/inspect', async (req: FastifyRequest, reply: FastifyReply) => {
  const adminUser = await loadAdminUserOrReply(req, reply)
  if (!adminUser) return

  const params = AdminInspectUserParams.safeParse(req.params)
  if (!params.success) return reply.code(400).send({ error: params.error.flatten() })

  const inspectedUser = await prisma.user.findUnique({
    where: { id: params.data.userId },
    select: {
      id: true,
      email: true,
      handle: true,
      name: true,
      bio: true,
      avatarUrl: true,
      coverUrl: true,
      createdAt: true,
      lastLoginAt: true,
      premiumStatus: true,
      communityFollows: {
        orderBy: [{ home: 'desc' }, { createdAt: 'asc' }],
        take: 8,
        select: {
          provinceCode: true,
          communitySlug: true,
          home: true,
        },
      },
      _count: {
        select: {
          posts: true,
          comments: true,
          businesses: true,
          contentReportsFiled: true,
          contentReportsTargeting: true,
          jobApplications: true,
          jobPostingsCreated: true,
          communityFollows: true,
        },
      },
    },
  })

  if (!inspectedUser) return reply.code(404).send({ error: 'user_not_found' })

  const [recentPosts, recentComments, recentReports] = await Promise.all([
    prisma.post.findMany({
      where: { authorId: inspectedUser.id },
      orderBy: [{ createdAt: 'desc' }],
      take: 20,
      select: {
        id: true,
        title: true,
        body: true,
        createdAt: true,
        moderationStatus: true,
        seoSlug: true,
        provinceCode: true,
        communitySlug: true,
        business: {
          select: {
            provinceCode: true,
            communitySlug: true,
          },
        },
        author: {
          select: {
            handle: true,
          },
        },
      },
    }),
    prisma.comment.findMany({
      where: { userId: inspectedUser.id },
      orderBy: [{ createdAt: 'desc' }],
      take: 5,
      select: {
        id: true,
        body: true,
        createdAt: true,
        post: {
          select: {
            id: true,
            title: true,
            body: true,
            seoSlug: true,
            provinceCode: true,
            communitySlug: true,
            business: {
              select: {
                provinceCode: true,
                communitySlug: true,
              },
            },
            author: {
              select: {
                handle: true,
              },
            },
          },
        },
      },
    }),
    prisma.contentReport.findMany({
      where: { reportedUserId: inspectedUser.id },
      orderBy: [{ createdAt: 'desc' }],
      take: 5,
      select: {
        id: true,
        targetType: true,
        targetLabel: true,
        targetUrl: true,
        reasons: true,
        status: true,
        createdAt: true,
      },
    }),
  ])

  return reply.send({
    user: {
      ...formatAdminUserSummary(inspectedUser),
      email: inspectedUser.email,
      bio: inspectedUser.bio ? sanitizePlainText(inspectedUser.bio) : null,
      createdAt: inspectedUser.createdAt.toISOString(),
      lastLoginAt: inspectedUser.lastLoginAt?.toISOString() ?? null,
      premiumStatus: inspectedUser.premiumStatus,
      communities: {
        count: inspectedUser._count.communityFollows,
        items: inspectedUser.communityFollows.map((community: any) => ({
          provinceCode: community.provinceCode,
          communitySlug: community.communitySlug,
          home: community.home,
          label: formatCommunityFollowLabel(community),
          href: buildCommunityHref(community.provinceCode, community.communitySlug),
        })),
      },
    },
    stats: {
      posts: inspectedUser._count.posts,
      comments: inspectedUser._count.comments,
      organizationsOwned: inspectedUser._count.businesses,
      reportsFiled: inspectedUser._count.contentReportsFiled,
      reportsAgainst: inspectedUser._count.contentReportsTargeting,
      jobApplications: inspectedUser._count.jobApplications,
      jobsCreated: inspectedUser._count.jobPostingsCreated,
      communities: inspectedUser._count.communityFollows,
    },
    recentPosts: recentPosts.map((entry: any) => ({
      id: entry.id,
      title: entry.title?.trim() || sanitizePlainText(entry.body).slice(0, 90) || 'Untitled post',
      createdAt: entry.createdAt.toISOString(),
      moderationStatus: entry.moderationStatus,
      url: buildPostHrefForAdmin(entry),
    })),
    recentComments: recentComments.map((entry: any) => ({
      id: entry.id,
      body: sanitizePlainText(entry.body).slice(0, 160).trim(),
      createdAt: entry.createdAt.toISOString(),
      post: {
        id: entry.post.id,
        title: entry.post.title?.trim() || sanitizePlainText(entry.post.body).slice(0, 90) || 'Untitled post',
        url: buildPostHrefForAdmin(entry.post),
      },
    })),
    recentReports: recentReports.map((entry: any) => ({
      id: entry.id,
      targetType: entry.targetType,
      targetLabel: entry.targetLabel,
      targetUrl: entry.targetUrl,
      reasons: entry.reasons,
      status: entry.status,
      createdAt: entry.createdAt.toISOString(),
    })),
  })
})

app.get('/notifications', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const userId = (req as any).user?.id
    if (!userId) return reply.code(401).send({ error: 'unauthorized' })

    const parse = NotificationListQuery.safeParse(req.query)
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const { limit, cursor } = parse.data
    const baseWhere: Prisma.NotificationWhereInput = {
      userId,
      type: { notIn: [...NOTIFICATION_FEED_EXCLUDED_TYPES] },
    }

    const [rows, unreadCount] = await Promise.all<[NotificationRecord[], number]>([
      prisma.notification.findMany({
        where: baseWhere,
        orderBy: { createdAt: 'desc' },
        take: limit + 1,
        ...(cursor ? { cursor: { id: cursor }, skip: 1 } : {}),
        select: NOTIFICATION_SELECT,
      }),
      prisma.notification.count({
        where: {
          userId,
          readAt: null,
          type: { notIn: [...NOTIFICATION_FEED_EXCLUDED_TYPES] },
        },
      }),
    ])

    const actorIds = Array.from(new Set(rows.map((row) => row.actorId).filter((id): id is string => Boolean(id))))
    const actors: FriendUser[] = actorIds.length
      ? await prisma.user.findMany({ where: { id: { in: actorIds } }, select: FRIEND_USER_SELECT })
      : []
    const actorMap = new Map(actors.map((actor) => [actor.id, formatFriendUser(actor)]))

    let nextCursor: string | undefined
    if (rows.length > limit) {
      const next = rows.pop()!
      nextCursor = next.id
    }

    return reply.send({
      items: rows.map((record) => ({
        ...formatNotification(record),
        actor: record.actorId ? actorMap.get(record.actorId) ?? null : null,
      })),
      nextCursor,
      unreadCount,
    })
  }),
)

app.get('/search/users', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const userId = (req as any).user?.id
    if (!userId) return reply.code(401).send({ error: 'unauthorized' })

    const parse = UserSearchQuery.safeParse(req.query)
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const { q, limit } = parse.data
    const normalizedQuery = normalizeSearchTerm(q)
    if (!normalizedQuery) {
      return reply.send({ items: [] })
    }

    const results = await searchUsersForQuery({ viewerId: userId, query: normalizedQuery, limit })

    return reply.send({
      items: results,
    })
  }),
)

app.get('/search', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const userId = (req as any).user?.id
    if (!userId) return reply.code(401).send({ error: 'unauthorized' })

    const parse = CombinedSearchQuery.safeParse(req.query)
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const { q, type, limit, peopleLimit, communityLimit, organizationLimit, eventLimit, marketLimit, postLimit } = parse.data
    const normalizedQuery = normalizeSearchTerm(q)
    if (!normalizedQuery) {
      return reply.send({ people: [], communities: [], organizations: [], events: [], market: [], posts: [], meta: { type } })
    }

    if (type === 'people') {
      const take = limit + 1
      const peopleResults = await searchUsersForQuery({ viewerId: userId, query: normalizedQuery, limit: take })
      const peopleHasMore = peopleResults.length > limit
      const trimmedPeople = peopleHasMore ? peopleResults.slice(0, limit) : peopleResults
      return reply.send({ people: trimmedPeople, meta: { type, peopleHasMore } })
    }

    if (type === 'communities') {
      const take = limit + 1
      const communityResults = await searchCommunitiesForQuery(normalizedQuery, take)
      const communitiesHasMore = communityResults.length > limit
      const trimmedCommunities = communitiesHasMore ? communityResults.slice(0, limit) : communityResults
      return reply.send({ communities: trimmedCommunities, meta: { type, communitiesHasMore } })
    }

    if (type === 'organizations') {
      const take = limit + 1
      const organizationResults = await searchOrganizationsForQuery(normalizedQuery, take)
      const organizationsHasMore = organizationResults.length > limit
      const trimmedOrganizations = organizationsHasMore ? organizationResults.slice(0, limit) : organizationResults
      return reply.send({ organizations: trimmedOrganizations, meta: { type, organizationsHasMore } })
    }

    if (type === 'events') {
      const take = limit + 1
      const eventResults = await searchEventsForQuery({ viewerId: userId, query: normalizedQuery, limit: take })
      const eventsHasMore = eventResults.length > limit
      const trimmedEvents = eventsHasMore ? eventResults.slice(0, limit) : eventResults
      return reply.send({ events: trimmedEvents, meta: { type, eventsHasMore } })
    }

    if (type === 'market') {
      const take = limit + 1
      const marketResults = await searchMarketListingsForQuery(normalizedQuery, take)
      const marketHasMore = marketResults.length > limit
      const trimmedMarket = marketHasMore ? marketResults.slice(0, limit) : marketResults
      return reply.send({ market: trimmedMarket, meta: { type, marketHasMore } })
    }

    if (type === 'posts') {
      const take = limit + 1
      const postResults = await searchCommunityPostsForQuery(normalizedQuery, take)
      const postsHasMore = postResults.length > limit
      const trimmedPosts = postsHasMore ? postResults.slice(0, limit) : postResults
      return reply.send({ posts: trimmedPosts, meta: { type, postsHasMore } })
    }

    const peopleTake = peopleLimit + 1
    const communityTake = communityLimit + 1
    const organizationTake = organizationLimit + 1
    const eventTake = eventLimit + 1
    const marketTake = marketLimit + 1
    const postTake = postLimit + 1
    const [peopleResults, communityResults, organizationResults, eventResults, marketResults, postResults] = await Promise.all([
      searchUsersForQuery({ viewerId: userId, query: normalizedQuery, limit: peopleTake }),
      searchCommunitiesForQuery(normalizedQuery, communityTake),
      searchOrganizationsForQuery(normalizedQuery, organizationTake),
      searchEventsForQuery({ viewerId: userId, query: normalizedQuery, limit: eventTake }),
      searchMarketListingsForQuery(normalizedQuery, marketTake),
      searchCommunityPostsForQuery(normalizedQuery, postTake),
    ])

    const peopleHasMore = peopleResults.length > peopleLimit
    const communitiesHasMore = communityResults.length > communityLimit
    const organizationsHasMore = organizationResults.length > organizationLimit
    const eventsHasMore = eventResults.length > eventLimit
    const marketHasMore = marketResults.length > marketLimit
    const postsHasMore = postResults.length > postLimit

    return reply.send({
      people: peopleHasMore ? peopleResults.slice(0, peopleLimit) : peopleResults,
      communities: communitiesHasMore ? communityResults.slice(0, communityLimit) : communityResults,
      organizations: organizationsHasMore ? organizationResults.slice(0, organizationLimit) : organizationResults,
      events: eventsHasMore ? eventResults.slice(0, eventLimit) : eventResults,
      market: marketHasMore ? marketResults.slice(0, marketLimit) : marketResults,
      posts: postsHasMore ? postResults.slice(0, postLimit) : postResults,
      meta: {
        type,
        peopleHasMore,
        communitiesHasMore,
        organizationsHasMore,
        eventsHasMore,
        marketHasMore,
        postsHasMore,
      },
    })
  }),
)

app.post('/notifications/:id/respond', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const userId = (req as any).user?.id
    if (!userId) return reply.code(401).send({ error: 'unauthorized' })

    const params = NotificationRespondParams.safeParse(req.params)
    if (!params.success) return reply.code(400).send({ error: params.error.flatten() })
    const body = NotificationRespondBody.safeParse(req.body ?? {})
    if (!body.success) return reply.code(400).send({ error: body.error.flatten() })

    const notification = await prisma.notification.findFirst({
      where: { id: params.data.id, userId },
      select: NOTIFICATION_SELECT,
    })
    if (!notification) return reply.code(404).send({ error: 'notification_not_found' })

    if (notification.type === FAMILY_NOTIFICATION_TYPES.FRIEND_REQUEST) {
      const payload = notification.payload && typeof notification.payload === 'object' && !Array.isArray(notification.payload)
        ? (notification.payload as Record<string, unknown>)
        : null
      if (!payload) return reply.code(400).send({ error: 'invalid_notification_payload' })

      const statusRaw = typeof payload.status === 'string' ? payload.status.trim().toLowerCase() : 'pending'
      if (statusRaw !== 'pending') {
        return reply.code(409).send({ error: 'invitation_not_pending' })
      }

      const requestId = typeof payload.requestId === 'string' ? payload.requestId.trim() : ''
      if (!requestId) return reply.code(400).send({ error: 'invalid_notification_payload' })

      const requesterParentId = notification.actorId
      if (!requesterParentId) return reply.code(400).send({ error: 'invalid_notification_payload' })

      const [requesterParent, targetParent] = await Promise.all([
        prisma.user.findUnique({ where: { id: requesterParentId }, select: { id: true, communityMeta: true } }),
        prisma.user.findUnique({ where: { id: userId }, select: { id: true, communityMeta: true } }),
      ])
      if (!requesterParent || !targetParent) return reply.code(404).send({ error: 'not_found' })

      const requesterRequests = getStoredFamilyFriendRequests(requesterParent.communityMeta)
      const targetRequests = getStoredFamilyFriendRequests(targetParent.communityMeta)
      const existingRequest = targetRequests.find((request) => request.id === requestId) ?? requesterRequests.find((request) => request.id === requestId)
      if (!existingRequest) return reply.code(404).send({ error: 'invite_not_found' })
      if (existingRequest.status !== 'pending') {
        return reply.code(409).send({ error: 'invitation_not_pending' })
      }

      const nowIso = new Date().toISOString()
      const nextStatus: FamilyFriendRequestStatus = body.data.action === 'accept' ? 'accepted' : 'rejected'
      const nextRequest: FamilyFriendRequestRecord = {
        ...existingRequest,
        status: nextStatus,
        respondedAt: nowIso,
      }

      const requesterBaseMeta = readBaseCommunityMeta(requesterParent.communityMeta ?? null)
      writeStoredFamilyFriendRequests(requesterBaseMeta, upsertFamilyFriendRequest(requesterRequests, nextRequest))

      const targetBaseMeta = readBaseCommunityMeta(targetParent.communityMeta ?? null)
      writeStoredFamilyFriendRequests(targetBaseMeta, upsertFamilyFriendRequest(targetRequests, nextRequest))

      if (body.data.action === 'accept') {
        const requesterFriendships = getStoredFamilyFriendships(requesterParent.communityMeta)
        const targetFriendships = getStoredFamilyFriendships(targetParent.communityMeta)

        writeStoredFamilyFriendships(
          requesterBaseMeta,
          upsertFamilyFriendship(requesterFriendships, {
            id: nextRequest.id,
            memberId: nextRequest.requesterMemberId,
            peerMemberId: nextRequest.targetMemberId,
            peerParentId: nextRequest.targetParentId,
            peerDisplayName: nextRequest.targetDisplayName,
            peerUsername: nextRequest.targetUsername,
            peerAvatarUrl: nextRequest.targetAvatarUrl ?? null,
            peerCoverUrl: nextRequest.targetCoverUrl ?? null,
            createdAt: nowIso,
          }),
        )

        writeStoredFamilyFriendships(
          targetBaseMeta,
          upsertFamilyFriendship(targetFriendships, {
            id: nextRequest.id,
            memberId: nextRequest.targetMemberId,
            peerMemberId: nextRequest.requesterMemberId,
            peerParentId: nextRequest.requesterParentId,
            peerDisplayName: nextRequest.requesterDisplayName,
            peerUsername: nextRequest.requesterUsername,
            peerAvatarUrl: nextRequest.requesterAvatarUrl ?? null,
            peerCoverUrl: nextRequest.requesterCoverUrl ?? null,
            createdAt: nowIso,
          }),
        )
      }

      const nextPayload: Prisma.InputJsonValue = {
        ...payload,
        status: nextStatus,
        respondedAt: nowIso,
      }

      await prisma.$transaction([
        prisma.user.update({
          where: { id: requesterParentId },
          data: { communityMeta: requesterBaseMeta as Prisma.InputJsonValue },
        }),
        prisma.user.update({
          where: { id: userId },
          data: { communityMeta: targetBaseMeta as Prisma.InputJsonValue },
        }),
        prisma.notification.update({
          where: { id: notification.id },
          data: {
            payload: nextPayload,
            readAt: notification.readAt ?? new Date(),
          },
        }),
      ])

      return reply.send({ ok: true, status: nextStatus })
    }

    if (notification.type !== EVENT_NOTIFICATION_TYPES.GUEST_SPEAKER_INVITE && notification.type !== EVENT_NOTIFICATION_TYPES.SPONSOR_INVITE) {
      return reply.code(400).send({ error: 'notification_not_actionable' })
    }

    const payload = notification.payload && typeof notification.payload === 'object' && !Array.isArray(notification.payload)
      ? (notification.payload as Record<string, unknown>)
      : null
    if (!payload) return reply.code(400).send({ error: 'invalid_notification_payload' })

    const statusRaw = typeof payload.status === 'string' ? payload.status.trim().toLowerCase() : 'pending'
    if (statusRaw !== 'pending') {
      return reply.code(409).send({ error: 'invitation_not_pending' })
    }

    const hostOrganizationId = typeof payload.hostOrganizationId === 'string' ? payload.hostOrganizationId : ''
    const eventId = typeof payload.eventId === 'string' ? payload.eventId : ''
    if (!hostOrganizationId || !eventId) {
      return reply.code(400).send({ error: 'invalid_notification_payload' })
    }

    const hostOrg = await prisma.business.findUnique({
      where: { id: hostOrganizationId },
      select: { id: true, metadata: true, provinceCode: true, communitySlug: true, slug: true },
    })
    if (!hostOrg) return reply.code(404).send({ error: 'organization_not_found' })

    const current = readOrganizationSystemState(hostOrg.metadata)
    const eventIndex = current.events.findIndex((entry) => entry.id === eventId)
    if (eventIndex < 0) return reply.code(404).send({ error: 'event_not_found' })
    const previousEvent = current.events[eventIndex]
    if (!previousEvent) return reply.code(404).send({ error: 'event_not_found' })

    const nowIso = new Date().toISOString()
    const nextStatus = body.data.action === 'accept' ? 'ACCEPTED' : 'DECLINED'
    const nextStatusLower = body.data.action === 'accept' ? 'accepted' : 'declined'
    const nextEvent: OrgEventDefinition = {
      ...previousEvent,
      guestSpeakerInvites: [...(previousEvent.guestSpeakerInvites ?? [])],
      sponsorInvites: [...(previousEvent.sponsorInvites ?? [])],
      updatedAt: nowIso,
    }

    if (notification.type === EVENT_NOTIFICATION_TYPES.GUEST_SPEAKER_INVITE) {
      const inviteIndex = nextEvent.guestSpeakerInvites.findIndex((invite) => invite.userId === userId)
      if (inviteIndex < 0) return reply.code(404).send({ error: 'invite_not_found' })
      const invite = nextEvent.guestSpeakerInvites[inviteIndex]
      if (!invite || invite.status !== 'PENDING') {
        return reply.code(409).send({ error: 'invitation_not_pending' })
      }
      nextEvent.guestSpeakerInvites[inviteIndex] = {
        ...invite,
        status: nextStatus,
        respondedAt: nowIso,
        respondedByUserId: userId,
      }
    } else {
      const targetOrganizationId = typeof payload.targetOrganizationId === 'string' ? payload.targetOrganizationId : ''
      if (!targetOrganizationId) return reply.code(400).send({ error: 'invalid_notification_payload' })

      const targetOrg = await prisma.business.findUnique({
        where: { id: targetOrganizationId },
        select: { id: true, ownerId: true },
      })
      if (!targetOrg) return reply.code(404).send({ error: 'organization_not_found' })

      let authorized = targetOrg.ownerId === userId
      if (!authorized) {
        const membership = await prisma.businessMembership.findUnique({
          where: { businessId_userId: { businessId: targetOrg.id, userId } },
          select: { role: true },
        })
        authorized = membership?.role === 'OWNER' || membership?.role === 'MANAGER'
      }
      if (!authorized) return reply.code(403).send({ error: 'forbidden' })

      const inviteIndex = nextEvent.sponsorInvites.findIndex((invite) => invite.organizationId === targetOrganizationId)
      if (inviteIndex < 0) return reply.code(404).send({ error: 'invite_not_found' })
      const invite = nextEvent.sponsorInvites[inviteIndex]
      if (!invite || invite.status !== 'PENDING') {
        return reply.code(409).send({ error: 'invitation_not_pending' })
      }
      nextEvent.sponsorInvites[inviteIndex] = {
        ...invite,
        status: nextStatus,
        respondedAt: nowIso,
        respondedByUserId: userId,
      }
    }

    const nextEvents = [...current.events]
    nextEvents[eventIndex] = nextEvent
    const nextSystem: OrganizationSystemState = { ...current, events: nextEvents }

    await prisma.business.update({
      where: { id: hostOrg.id },
      data: {
        metadata: mergeOrganizationSystemStateIntoMetadata(hostOrg.metadata, nextSystem),
      },
      select: { id: true },
    })

    const nextPayload: Prisma.InputJsonValue = {
      ...payload,
      status: body.data.action === 'accept' ? 'accepted' : 'rejected',
      respondedAt: nowIso,
    }

    await prisma.notification.update({
      where: { id: notification.id },
      data: {
        payload: nextPayload,
        readAt: notification.readAt ?? new Date(),
      },
    })

    if (notification.actorId && notification.actorId !== userId) {
      const inviteKind = notification.type === EVENT_NOTIFICATION_TYPES.GUEST_SPEAKER_INVITE ? 'guest_speaker' : 'sponsor'
      const responseType =
        notification.type === EVENT_NOTIFICATION_TYPES.GUEST_SPEAKER_INVITE
          ? EVENT_NOTIFICATION_TYPES.GUEST_SPEAKER_RESPONSE
          : EVENT_NOTIFICATION_TYPES.SPONSOR_RESPONSE

      await createNotificationRecord({
        userId: notification.actorId,
        actorId: userId,
        type: responseType,
        payload: {
          invitationKind: inviteKind,
          status: nextStatusLower,
          eventId,
          eventTitle:
            typeof payload.eventTitle === 'string' && payload.eventTitle.trim()
              ? payload.eventTitle.trim()
              : previousEvent.title,
          url:
            typeof payload.url === 'string' && payload.url.trim().startsWith('/')
              ? payload.url.trim()
              : hostOrg.provinceCode && hostOrg.communitySlug && hostOrg.slug
                ? `/com/${encodeURIComponent(hostOrg.provinceCode)}/${encodeURIComponent(hostOrg.communitySlug)}/orgs/${encodeURIComponent(hostOrg.slug)}/events/${encodeURIComponent(eventId)}`
                : '/notifications',
          respondedAt: nowIso,
        },
      })
    }

    return reply.send({ ok: true, status: body.data.action === 'accept' ? 'accepted' : 'rejected' })
  }),
)

app.post('/notifications/ack', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const userId = (req as any).user?.id
    if (!userId) return reply.code(401).send({ error: 'unauthorized' })

    const parse = NotificationAckInput.safeParse(req.body ?? {})
    if (!parse.success) return reply.code(400).send({ error: parse.error.flatten() })

    const { ids, before } = parse.data
    const where: Prisma.NotificationWhereInput = { userId }
    if (ids?.length) {
      where.id = { in: ids }
    }
    if (before) {
      where.createdAt = { lte: before }
    }

    const result = await prisma.notification.updateMany({ where, data: { readAt: new Date() } })
    return reply.send({ updated: result.count })
  }),
)

// SSE notifications (skeleton)
app.get('/notifications/stream', async (req: FastifyRequest, reply: FastifyReply) => {
  const userId = await resolveStreamUserId(req)
  if (!userId) {
    req.log.warn('notifications_stream_unauthorized')
    return reply.code(401).send({ error: 'unauthorized' })
  }
  req.log.info({ userId }, 'notifications_stream_connected')
  const sub = new IORedis(REDIS_URL)
  const channel = `${NOTIFICATION_CHANNEL_PREFIX}${userId}`
  const connectionId = randomUUID()
  await sub.subscribe(channel)
  await markUserRealtimeOnline(userId, connectionId)
  reply.sse({ data: JSON.stringify({ type: 'connected' }) })

  const heartbeat = setInterval(() => {
    void markUserRealtimeOnline(userId, connectionId).catch((err) => {
      req.log.warn({ err, userId }, 'notifications_stream_presence_refresh_failed')
    })
    reply.sse({ data: JSON.stringify({ type: 'ping' }) })
  }, 30000)

  sub.on('message', (_chan: string, message: string) => {
    req.log.debug({ userId, size: message.length }, 'notifications_stream_dispatch')
    reply.sse({ data: message })
  })
  req.raw.on('close', async () => {
    clearInterval(heartbeat)
    req.log.info({ userId }, 'notifications_stream_disconnected')
    await clearUserRealtimeOnline(userId, connectionId).catch((err) => {
      req.log.warn({ err, userId }, 'notifications_stream_presence_clear_failed')
    })
    await sub.unsubscribe(channel)
    sub.disconnect()
  })
})

app.get('/home/right-rail', async (req: FastifyRequest, reply: FastifyReply) => {
  const authContext = await loadViewerAuthContext(req)
  if (!authContext) return reply.code(401).send({ error: 'unauthorized' })

  if (authContext.actor === 'family_member') {
    return {
      userHandle: undefined,
      totalFriends: 1,
      friends: [{
        ...formatFriendUser(authContext.member.parent),
        newPosts: 0,
      }],
      communities: [],
    }
  }

  const userId = authContext.userId

  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { handle: true, lastViewedFriendsAt: true, lastViewedHomeAt: true },
  })

  // 1. Friends
  const friendIds = await loadAcceptedFriendIds(userId)

  // Determine the threshold for "new" friend posts
  const friendsThreshold = [user?.lastViewedFriendsAt, user?.lastViewedHomeAt]
    .filter((d): d is Date => !!d)
    .sort((a, b) => b.getTime() - a.getTime())[0] ?? new Date(0)

  // Get new post counts
  const activeFriendCounts = friendIds.length
    ? await prisma.post.groupBy({
        by: ['authorId'],
        where: {
          authorId: { in: friendIds },
          createdAt: { gt: friendsThreshold },
        },
        _count: { id: true },
      })
    : []

  const friendCountMap = new Map<string, number>()
  activeFriendCounts.forEach((row: { authorId: string; _count: { id: number } }) => {
    friendCountMap.set(row.authorId, row._count.id)
  })

  // Prioritize friends with new posts, then fill with others
  // Sort active counts descending
  const sortedActive = [...activeFriendCounts].sort((a: any, b: any) => b._count.id - a._count.id)
  const activeIds = sortedActive.map((row: any) => row.authorId)
  const activeIdSet = new Set(activeIds)
  const otherIds = friendIds.filter((id) => !activeIdSet.has(id))

  // Combine and limit to 10
  // We want active ones first, then random others? Or just others.
  // Let's shuffle others to keep it fresh if they have many friends
  const shuffledOthers = otherIds.sort(() => 0.5 - Math.random())
  const selectedIds = [...activeIds, ...shuffledOthers].slice(0, 10)

  const friends = selectedIds.length
    ? await prisma.user.findMany({
        where: { id: { in: selectedIds } },
        select: {
          id: true,
          handle: true,
          name: true,
          avatarUrl: true,
          coverUrl: true,
          bio: true,
          communityMeta: true, // To get home community
        },
      })
    : []

  const normalizedFriends = friends.map((friend: any) => normalizeUserMedia(friend))

  const friendsWithCounts = normalizedFriends.map((friend: any) => ({
    ...friend,
    newPosts: friendCountMap.get(friend.id) ?? 0,
  }))

  // Sort by new posts desc
  const finalFriends = friendsWithCounts.sort((a: any, b: any) => b.newPosts - a.newPosts)

  // 2. Communities
  const follows = await prisma.communityFollow.findMany({
    where: { userId },
    select: { provinceCode: true, communitySlug: true, lastViewedAt: true },
  })

  const followThresholds = follows.map((follow: any) => {
    const lastViewed = [
      follow.lastViewedAt,
      user?.lastViewedHomeAt,
      // user?.lastViewedCommunitiesAt
    ]
      .filter((d): d is Date => !!d)
      .sort((a, b) => b.getTime() - a.getTime())[0] ?? new Date(0)

    return {
      ...follow,
      lastViewed,
    }
  })

  const communityOr = followThresholds.map((follow: any) => ({
    provinceCode: follow.provinceCode,
    communitySlug: follow.communitySlug,
    createdAt: { gt: follow.lastViewed },
  }))

  const groupedCommunityCounts = communityOr.length
    ? await prisma.post.groupBy({
        by: ['provinceCode', 'communitySlug'],
        where: {
          OR: communityOr,
        },
        _count: { id: true },
      })
    : []

  const communityCountMap = new Map<string, number>()
  groupedCommunityCounts.forEach((row: any) => {
    const key = `${row.provinceCode}:${row.communitySlug}`
    communityCountMap.set(key, row._count?.id ?? 0)
  })

  const cityRows = follows.length
    ? await prisma.city.findMany({
        where: {
          OR: follows.map((follow: any) => ({
            provinceCode: follow.provinceCode,
            communitySlug: follow.communitySlug,
          })),
        },
        select: { provinceCode: true, communitySlug: true, name: true, communityName: true },
      })
    : []

  const cityNameMap = new Map<string, string>()
  cityRows.forEach((row: any) => {
    const key = `${row.provinceCode}:${row.communitySlug}`
    const name = row?.communityName ?? row?.name ?? null
    if (name) cityNameMap.set(key, name)
  })

  const communitiesWithCounts = followThresholds.map((follow: any) => {
    const key = `${follow.provinceCode}:${follow.communitySlug}`
    return {
      provinceCode: follow.provinceCode,
      communitySlug: follow.communitySlug,
      name: cityNameMap.get(key) ?? follow.communitySlug,
      newPosts: communityCountMap.get(key) ?? 0,
    }
  })

  // Limit 5, sort by new posts desc
  const topCommunities = communitiesWithCounts.sort((a: any, b: any) => b.newPosts - a.newPosts).slice(0, 5)

  return {
    userHandle: user?.handle,
    totalFriends: friendIds.length,
    friends: finalFriends,
    communities: topCommunities,
  }
})

app.get('/users/:handle/friends', async (req: FastifyRequest, reply: FastifyReply) =>
  withSchemaGuard(req, reply, async () => {
    const params = HandleParam.safeParse(req.params)
    if (!params.success) return reply.code(400).send({ error: params.error.flatten() })

    const handle = params.data.handle.replace(/^@/, '').toLowerCase()
    const user = await prisma.user.findUnique({
      where: { handle },
      select: { id: true, handle: true },
    })

    if (!user) return reply.code(404).send({ error: 'not_found' })

    const friendIds = await loadAcceptedFriendIds(user.id)

    const friends = await prisma.user.findMany({
      where: { id: { in: friendIds } },
      select: {
        id: true,
        handle: true,
        name: true,
        avatarUrl: true,
        coverUrl: true,
        bio: true,
      },
      orderBy: [{ name: 'asc' }, { handle: 'asc' }],
    })

    const items = friends.map((friend: any) => ({
      id: friend.id,
      handle: friend.handle,
      name: friend.name,
      avatarUrl: normalizeMediaUrl(friend.avatarUrl ?? null),
      coverUrl: normalizeMediaUrl(friend.coverUrl ?? null),
      bio: friend.bio,
    }))

    return { userHandle: user.handle, items }
  }),
)

